package com.deathlog;

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.nio.charset.StandardCharsets;
import java.util.HashMap;
import java.util.Map;

/**
 * Where a tile is: the area name for its map region (regions.tsv — RuneLite's own Discord plugin list of cities,
 * dungeons, bosses, minigames and raids), and the Wilderness level worked out from the tile.
 */
final class Areas
{
	/** A place: its name (null = not a named area), its type, and the Wilderness level (0 = none). */
	static final class Place
	{
		final String name;
		final String type;
		final int wildy;

		Place(String name, String type, int wildy)
		{
			this.name = name;
			this.type = type;
			this.wildy = wildy;
		}
	}

	private final Map<Integer, String[]> regions = new HashMap<>();

	/** Read the table from the plugin's resources. */
	static Areas load()
	{
		Areas a = new Areas();
		try (InputStream in = Areas.class.getResourceAsStream("regions.tsv"))
		{
			if (in != null)
			{
				a.read(new BufferedReader(new InputStreamReader(in, StandardCharsets.UTF_8)));
			}
		}
		catch (IOException e)
		{
			// no names, only tiles: the deaths are still recorded
		}
		return a;
	}

	void read(BufferedReader r) throws IOException
	{
		for (String line = r.readLine(); line != null; line = r.readLine())
		{
			if (line.isEmpty() || line.startsWith("#"))
			{
				continue;
			}
			String[] p = line.split("\t");
			if (p.length >= 3)
			{
				try
				{
					regions.put(Integer.parseInt(p[0]), new String[]{p[1], p[2]});
				}
				catch (NumberFormatException e)
				{
					// a bad row is skipped
				}
			}
		}
	}

	int size()
	{
		return regions.size();
	}

	/** The place of a world map tile. */
	Place of(int x, int y, int plane)
	{
		int region = ((x >> 6) << 8) | (y >> 6);
		String[] r = regions.get(region);
		int w = wildernessLevel(x, y);
		if (r != null)
		{
			return new Place(r[0], r[1], w);
		}
		return w > 0 ? new Place("Wilderness level " + w, "WILDERNESS", w) : new Place(null, null, 0);
	}

	/**
	 * The Wilderness level of a tile, 0 outside it: on the surface from y 3520 (level 1) up, 8 tiles a level; in the
	 * Wilderness dungeons the same from y 9920.
	 */
	static int wildernessLevel(int x, int y)
	{
		if (x >= 2944 && x < 3392 && y >= 3520 && y < 4000)
		{
			return Math.min(56, (y - 3520) / 8 + 1);
		}
		if (x >= 2944 && x < 3456 && y >= 9920 && y < 10400)
		{
			return Math.min(56, (y - 9920) / 8 + 1);
		}
		return 0;
	}
}

