package com.deathlog;

import java.util.ArrayList;
import java.util.Collection;
import java.util.Comparator;
import java.util.List;

/**
 * What was attacking you: every NPC or player that targeted you in the last few seconds. The game does not say whose hit
 * killed you, so the killer is the one still on you at the death — the strongest when several were (the others are
 * listed with it).
 */
final class Attackers
{
	/** Seconds of attacks that count: 16 ticks, about 10 seconds. */
	static final int WINDOW_TICKS = 16;

	static final class Attacker
	{
		final String name;
		/** NPC id; -1 for a player. */
		final int id;
		final int level;
		final boolean player;
		/** The last tick it was targeting you. */
		int lastTick;
		/** Still targeting you at the death. */
		boolean onYou;

		Attacker(String name, int id, int level, boolean player, int lastTick)
		{
			this.name = name;
			this.id = id;
			this.level = level;
			this.player = player;
			this.lastTick = lastTick;
		}
	}

	private Attackers()
	{
	}

	/** The ones that count at {@code tick}, the killer first; empty when nothing attacked you lately. */
	static List<Attacker> atDeath(Collection<Attacker> all, int tick)
	{
		List<Attacker> out = new ArrayList<>();
		for (Attacker a : all)
		{
			if (a.name != null && (a.onYou || tick - a.lastTick <= WINDOW_TICKS))
			{
				out.add(a);
			}
		}
		out.sort(Comparator.<Attacker, Boolean>comparing(a -> !a.onYou)
			.thenComparing(Comparator.<Attacker>comparingInt(a -> a.level).reversed())
			.thenComparing(Comparator.<Attacker>comparingInt(a -> a.lastTick).reversed()));
		return out;
	}
}

