 */package com.deathlog;

import java.awt.BasicStroke;
import java.awt.Color;
import java.awt.Dimension;
import java.awt.FontMetrics;
import java.awt.Graphics;
import java.awt.Graphics2D;
import java.awt.RenderingHints;
import java.awt.event.MouseEvent;
import javax.swing.JComponent;
import net.runelite.client.ui.ColorScheme;
import net.runelite.client.ui.FontManager;

/**
 * A bar chart for the Statistics window: a title, bars with their numbers, labels under them (thinned to fit), an
 * optional dashed line (a best, an average) and the bar under the mouse in a tooltip.
 */
final class BarChart extends JComponent
{
	static final Color BAR = new Color(0xA0, 0x3A, 0x30);
	static final Color HIGHLIGHT = new Color(0xE0, 0x4B, 0x3C);
	static final Color GOOD = new Color(0x4C, 0xC0, 0x5A);
	private static final Color GRID = new Color(0x4A, 0x4A, 0x4A);
	private static final Color TEXT = new Color(0xC8, 0xC8, 0xC8);

	private String title = "";
	private String[] labels = new String[0];
	private double[] values = new double[0];
	/** Per bar: its colour; null = BAR. */
	private Color[] colors = new Color[0];
	/** Per bar: the tooltip; null = "label: value". */
	private String[] tips = new String[0];
	private double line = -1;
	private String lineLabel;
	private String empty = "No data yet.";
	private Color background = ColorScheme.DARKER_GRAY_COLOR;
	private Color barColor = BAR;
	private Color lineColor = GOOD;
	private Color textColor = TEXT;
	private Color titleColor = Color.WHITE;
	private Color gridColor = GRID;

	BarChart(int width, int height)
	{
		setPreferredSize(new Dimension(width, height));
		setToolTipText("");
	}

	void set(String title, String[] labels, double[] values, Color[] colors, String[] tips)
	{
		this.title = title;
		this.labels = labels;
		this.values = values;
		this.colors = colors == null ? new Color[values.length] : colors;
		this.tips = tips == null ? new String[values.length] : tips;
		repaint();
	}

	void line(double value, String label)
	{
		line = value;
		lineLabel = label;
		repaint();
	}

	void empty(String text)
	{
		empty = text;
	}

	/** Colours from the panel's theme. */
	void theme(Theme t)
	{
		background = t.cardFill;
		barColor = t.bar;
		lineColor = t.good;
		textColor = t.dim;
		titleColor = t.title;
		gridColor = t.chip;
		repaint();
	}

	private boolean hasData()
	{
		for (double v : values)
		{
			if (v > 0)
			{
				return true;
			}
		}
		return false;
	}

	/** The bar area: {left, top, width, height}. */
	private int[] area()
	{
		return new int[]{34, 26, Math.max(10, getWidth() - 44), Math.max(10, getHeight() - 26 - 22)};
	}

	@Override
	public String getToolTipText(MouseEvent e)
	{
		int[] a = area();
		int n = values.length;
		if (n == 0 || e.getX() < a[0] || e.getX() >= a[0] + a[2])
		{
			return null;
		}
		int i = Math.min(n - 1, (e.getX() - a[0]) * n / a[2]);
		return tips[i] != null ? tips[i] : labels[i] + ": " + fmt(values[i]);
	}

	@Override
	protected void paintComponent(Graphics g0)
	{
		Graphics2D g = (Graphics2D) g0.create();
		g.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
		g.setColor(background);
		g.fillRect(0, 0, getWidth(), getHeight());
		g.setFont(FontManager.getRunescapeBoldFont());
		g.setColor(titleColor);
		g.drawString(title, 8, 16);
		g.setFont(FontManager.getRunescapeSmallFont());
		FontMetrics fm = g.getFontMetrics();
		int[] a = area();
		if (!hasData())
		{
			g.setColor(textColor);
			g.drawString(empty, a[0], a[1] + a[3] / 2);
			g.dispose();
			return;
		}
		double max = Math.max(line, 1);
		for (double v : values)
		{
			max = Math.max(max, v);
		}
		max = nice(max);
		// grid: 0, half, top
		for (int k = 0; k <= 2; k++)
		{
			int y = a[1] + a[3] - a[3] * k / 2;
			g.setColor(gridColor);
			g.drawLine(a[0], y, a[0] + a[2], y);
			g.setColor(textColor);
			String s = fmt(max * k / 2);
			g.drawString(s, a[0] - 4 - fm.stringWidth(s), y + 4);
		}
		int n = values.length;
		double slot = (double) a[2] / n;
		int w = Math.max(1, (int) (slot * 0.72));
		boolean numbers = slot >= 14;
		for (int i = 0; i < n; i++)
		{
			int h = values[i] <= 0 ? 0 : Math.max(2, (int) Math.round(a[3] * values[i] / max));
			int x = a[0] + (int) (i * slot + (slot - w) / 2);
			g.setColor(colors[i] != null ? colors[i] : barColor);
			g.fillRect(x, a[1] + a[3] - h, w, h);
			if (numbers && values[i] > 0)
			{
				String s = fmt(values[i]);
				g.setColor(Color.WHITE);
				g.drawString(s, x + (w - fm.stringWidth(s)) / 2, a[1] + a[3] - h - 2);
			}
		}
		// labels under the bars, every k-th so they do not overlap
		int widest = 1;
		for (String l : labels)
		{
			widest = Math.max(widest, fm.stringWidth(l));
		}
		int every = Math.max(1, (int) Math.ceil((widest + 6) / slot));
		g.setColor(textColor);
		for (int i = 0; i < n; i += every)
		{
			int cx = a[0] + (int) (i * slot + slot / 2);
			g.drawString(labels[i], cx - fm.stringWidth(labels[i]) / 2, a[1] + a[3] + 14);
		}
		if (line > 0)
		{
			int y = a[1] + a[3] - (int) Math.round(a[3] * line / max);
			g.setColor(lineColor);
			g.setStroke(new BasicStroke(1f, BasicStroke.CAP_BUTT, BasicStroke.JOIN_MITER, 1f, new float[]{4f, 3f}, 0f));
			g.drawLine(a[0], y, a[0] + a[2], y);
			if (lineLabel != null)
			{
				// in the title row, right side — never on top of a bar's number
				g.drawString("- - " + lineLabel, getWidth() - 8 - fm.stringWidth("- - " + lineLabel), 16);
			}
		}
		g.dispose();
	}

	/** A round top for the axis, not far over the tallest bar: 66 -> 70, 31 -> 40, 7 -> 7, 2.4 -> 2.5. */
	static double nice(double max)
	{
		double p = Math.pow(10, Math.floor(Math.log10(Math.max(1, max))));
		for (double m : new double[]{1, 1.2, 1.5, 2, 2.5, 3, 4, 5, 6, 7, 8, 10})
		{
			if (m * p >= max)
			{
				return m * p;
			}
		}
		return 10 * p;
	}

	private static String fmt(double v)
	{
		return v == Math.rint(v) ? String.valueOf((long) v) : String.format("%.1f", v);
	}
}

