package com.deathlog;

import java.util.HashMap;
import java.util.HashSet;
import java.util.Locale;
import java.util.Map;
import java.util.Set;
import java.util.regex.Matcher;
import java.util.regex.Pattern;

/**
 * Which boss a death belongs to, and the game's kill-count messages — so each boss shows its deaths beside its kills.
 * A boss is named the way its kill-count message names it ("Your TzKal-Zuk kill count is: 1."), so the two line up.
 */
final class Bosses
{
	/**
	 * The game's kill-count message — RuneLite's own pattern (ChatCommandsPlugin.KILLCOUNT_PATTERN, BSD-2): "Your Vorkath
	 * kill count is: 12.", "Your completed Theatre of Blood count is: 3.", "Your TzKal-Zuk kill count is: 1.".
	 */
	static final Pattern KILL_COUNT = Pattern.compile("Your (?<pre>completion count for |subdued |completed )?"
		+ "(?:<col=[0-9a-f]{6}>)?(?<boss>.+?)(?:</col>)? (?<post>(?:(?:kill|harvest|lap|completion|success|Total Ticket) )?"
		+ "(?:count )?)is: ?(?:<col=[0-9a-f]{6}>|@.+?@)(?<kc>[0-9,]+)</col>");

	/** The wave messages of the wave fights: "Wave: 31". */
	static final Pattern WAVE = Pattern.compile("^Wave: ?(\\d+)");

	/** Fights in waves, by area — their kill-count name. */
	static final Map<String, String> WAVE_AREAS = Map.of(
		"The Inferno", "TzKal-Zuk",
		"Tzhaar Fight Caves", "TzTok-Jad",
		"Fortis Colosseum", "Sol Heredit");

	/** Other areas whose deaths belong to one kill count. */
	private static final Map<String, String> AREA_BOSS = Map.of(
		"The Gauntlet", "Gauntlet",
		"Corrupted Gauntlet", "Corrupted Gauntlet");

	/**
	 * Bosses by their NPC's name (lower case, without "the ") -> their kill-count name. Names seen in a kill-count message
	 * are added as they come ({@link #learn}).
	 */
	private static final Map<String, String> BY_NPC = new HashMap<>();

	static
	{
		for (String b : new String[]{"Abyssal Sire", "Alchemical Hydra", "Amoxliatl", "Araxxor", "Artio", "Bryophyta",
			"Callisto", "Calvar'ion", "Cerberus", "Chaos Elemental", "Chaos Fanatic", "Commander Zilyana",
			"Corporeal Beast", "Crazy Archaeologist", "Dagannoth Prime", "Dagannoth Rex", "Dagannoth Supreme",
			"Deranged Archaeologist", "Doom of Mokhaiotl", "Duke Sucellus", "General Graardor", "Giant Mole", "Hespori",
			"K'ril Tsutsaroth", "Kalphite Queen", "King Black Dragon", "Kraken", "Kree'arra", "Leviathan", "Nex",
			"Nightmare", "Obor", "Phantom Muspah", "Phosani's Nightmare", "Sarachnis", "Scorpia", "Scurrius", "Skotizo",
			"Sol Heredit", "Spindel", "Tempoross", "Thermonuclear Smoke Devil", "TzKal-Zuk", "TzTok-Jad", "Vardorvis",
			"Venenatis", "Vet'ion", "Vorkath", "Whisperer", "Wintertodt", "Yama", "Zalcano", "Zulrah", "Hueycoatl",
			"Mimic", "Royal Titans"})
		{
			BY_NPC.put(key(b), b);
		}
		// NPC names that differ from their kill count
		BY_NPC.put("dusk", "Grotesque Guardians");
		BY_NPC.put("dawn", "Grotesque Guardians");
		BY_NPC.put("branda the fire queen", "Royal Titans");
		BY_NPC.put("eldric the ice king", "Royal Titans");
		for (String brother : new String[]{"ahrim the blighted", "dharok the wretched", "guthan the infested",
			"karil the tainted", "torag the corrupted", "verac the defiled"})
		{
			BY_NPC.put(brother, "Barrows Chests");
		}
	}

	private final Set<String> learned = new HashSet<>();

	/** A kill count from a game message: {boss, count}; null when it is not one. */
	static Object[] killCount(String message)
	{
		Matcher m = KILL_COUNT.matcher(message);
		if (!m.find())
		{
			return null;
		}
		String pre = m.group("pre");
		String post = m.group("post");
		if ((pre == null || pre.isEmpty()) && (post == null || post.isEmpty()))
		{
			return null;                        // "Your X is: N" without "kill count" — not a kill count
		}
		if (post != null && (post.startsWith("lap") || post.startsWith("harvest")))
		{
			return null;                        // agility laps, Herbiboar: nothing dies there
		}
		try
		{
			return new Object[]{m.group("boss"), Integer.parseInt(m.group("kc").replace(",", ""))};
		}
		catch (NumberFormatException e)
		{
			return null;
		}
	}

	/** A name seen in a kill-count message: a death to an NPC of that name is a boss death from now on. */
	void learn(String boss)
	{
		learned.add(key(boss));
	}

	/**
	 * The boss a death belongs to (its kill-count name), or null. A wave fight or a raid by where you died (anything
	 * there kills you "at the Inferno"); else the boss attacking you; else a boss's own area.
	 */
	String bossOf(String area, String areaType, String killer)
	{
		if (area != null && WAVE_AREAS.containsKey(area))
		{
			return WAVE_AREAS.get(area);
		}
		if (area != null && AREA_BOSS.containsKey(area))
		{
			return AREA_BOSS.get(area);
		}
		if ("RAIDS".equals(areaType) && area != null)
		{
			return area;
		}
		if (killer != null)
		{
			String k = key(killer);
			if (BY_NPC.containsKey(k))
			{
				return BY_NPC.get(k);
			}
			if (learned.contains(k))
			{
				return killer;
			}
		}
		return "BOSSES".equals(areaType) ? area : null;
	}

	/**
	 * The kill count a death's boss is compared with: the raids' and Dagannoth Kings' kill counts come in parts
	 * ("Theatre of Blood Hard Mode", "Dagannoth Rex") — they add up under the death's name.
	 */
	static boolean countsFor(String kcName, String boss)
	{
		if (kcName.equalsIgnoreCase(boss))
		{
			return true;
		}
		if ("Barrows Chests".equals(boss))
		{
			return kcName.toLowerCase(Locale.ROOT).startsWith("barrows chest");
		}
		if ("Dagannoth Kings".equals(boss))
		{
			return kcName.startsWith("Dagannoth ");
		}
		return ("Chambers of Xeric".equals(boss) || "Theatre of Blood".equals(boss) || "Tombs of Amascut".equals(boss))
			&& kcName.startsWith(boss);
	}

	/**
	 * A kill count worth a row with no deaths: a boss, a raid, a wave fight or Barrows — not a chest, a rumour or a
	 * minigame count.
	 */
	static boolean known(String kcName)
	{
		return BY_NPC.containsValue(kcName) || WAVE_AREAS.containsValue(kcName) || AREA_BOSS.containsValue(kcName)
			|| kcName.startsWith("Chambers of Xeric") || kcName.startsWith("Theatre of Blood")
			|| kcName.startsWith("Tombs of Amascut") || kcName.toLowerCase(Locale.ROOT).startsWith("barrows chest");
	}

	/** How a boss is shown: a wave fight by its place ("The Inferno (TzKal-Zuk)"), the rest by name. */
	static String display(String kcName)
	{
		for (Map.Entry<String, String> e : WAVE_AREAS.entrySet())
		{
			if (e.getValue().equals(kcName))
			{
				return e.getKey() + " (" + kcName + ")";
			}
		}
		return kcName;
	}

	/** Lower case, without a leading "the ". */
	static String key(String name)
	{
		String k = name.toLowerCase(Locale.ROOT).trim();
		return k.startsWith("the ") ? k.substring(4) : k;
	}
}

