import java.util.ArrayList;
import java.util.List;

/**
 * One death, as saved: one JSON line in the plugin's data folder (deaths/&lt;profile&gt;.jsonl). Every field is what the
 * client showed at the moment you died — nothing is sent anywhere.
 */
final class Death
{
	/** When, epoch ms. */
	long at;
	int world;
	/** Where, as a world map tile (an instance — the Inferno, a raid — is turned back into its map tile). */
	int x;
	int y;
	int plane;
	int region;
	/** The area's name ("The Inferno", "Varrock"); null = not a named area. */
	String area;
	/** BOSSES, CITIES, DUNGEONS, MINIGAMES, RAIDS, REGIONS, WILDERNESS; null = not known. */
	String areaType;
	/** The Wilderness level; 0 = not in the Wilderness. */
	int wildy;

	/** What was attacking you (the strongest, when several were); null = nothing seen attacking you. */
	String killer;
	/** Its NPC id; -1 = a player, or not known. */
	int killerId = -1;
	int killerLevel;
	/** A player killed you. */
	boolean pvp;
	/**
	 * In a raid: the room or boss you died at ("Great Olm", "Verzik Vitur"); null = not in a raid, or not known. Saved
	 * since 2026-11-07; older Chambers of Xeric deaths get theirs from their tile ({@link #room()}).
	 */
	String room;
	/** Everything else attacking you then. */
	List<String> others = new ArrayList<>();

	/** The last damage you took: "hit", "poison", "venom", "burn", "disease", "bleed", "doom". */
	String cause;
	/** The killing blow. */
	int lastHit;
	/** The biggest hit, the damage, and the number of hits in the last 10 seconds. */
	int maxHit;
	int damage;
	int hits;
	/** Prayer points left. */
	int prayer;
	/** Your combat level. */
	int combat;

	/** What your inventory and worn items were worth (Grand Exchange prices; untradeables count 0). */
	long carried;
	/** The most valuable of them, "name|gp" each. */
	List<String> top = new ArrayList<>();

	/** The boss, by its kill-count name ("TzKal-Zuk" for the Inferno); null = not a boss death. */
	String boss;
	/** The boss's kill count when you died (its kill-count messages so far); -1 = none seen yet. */
	int killCount = -1;
	/** The wave you died on (the Inferno, the Fight Caves, the Colosseum); 0 = not a wave fight. */
	int wave;
	/** Your own note (right-click a death in the panel). */
	String note;
	/** Not seen by Death Log: imported from this (DeathImport.FROM_SCREENSHOT) — the date only. Null = recorded live. */
	String from;

	/** Shown when nothing was targeting you and no raid room is known: the game never says what killed you. */
	static final String NO_ATTACKER = "No attacker seen";

	/** The raid room or boss you died at (see {@link #room}); null = none known. */
	String room()
	{
		if (room != null || from != null)
		{
			return room;
		}
		return RaidRooms.COX.equals(area) ? RaidRooms.cox(x, y, plane, region) : null;
	}

	/** What killed you for counting: the attacker, else the raid room; null = neither known. */
	String who()
	{
		return killer != null ? killer : room();
	}

	/** "Jal-Xil (level 370)" / "Venom, fighting Zulrah (level 725)" / "Great Olm" / "No attacker seen". */
	String killedBy()
	{
		if (from != null)
		{
			return "From before Death Log";
		}
		String what = killer == null ? room() : killer + (killerLevel > 0 ? " (level " + killerLevel + ")" : "");
		if (cause != null && !"hit".equals(cause))
		{
			String c = Character.toUpperCase(cause.charAt(0)) + cause.substring(1);
			return what == null ? c : c + ", fighting " + what;
		}
		return what == null ? NO_ATTACKER : what;
	}

	/** Why the killer shown is what it is, when it isn't an attacker (two lines); null = an attacker was seen. */
	String killerNote()
	{
		if (from != null || killer != null)
		{
			return null;
		}
		return room() != null
			? "Nothing was targeting you (the Great Olm, for one, never does),\nso this is the raid room you died in."
			: "Nothing was targeting you when you died,\nand the game doesn't say what killed you.";
	}

	/** "The Inferno, wave 31" / "Wilderness level 12" / "3222, 3218". */
	String place()
	{
		if (from != null)
		{
			return "Imported from a " + from + " - the date only";
		}
		String p = area != null ? area : x + ", " + y + (plane > 0 ? ", floor " + plane : "");
		if (wildy > 0 && (area == null || !area.startsWith("Wilderness")))
		{
			p += " (Wilderness " + wildy + ")";
		}
		return wave > 0 ? p + ", wave " + wave : p;
	}
}

