package com.deathlog;

import java.text.SimpleDateFormat;
import java.util.Date;
import java.util.List;

/** Every death as a spreadsheet (CSV) — one row each, oldest first. */
final class DeathCsv
{
	static final String HEADER = "number,date,world,killed by,killer level,player,also attacking,cause,area,area type,"
		+ "wilderness level,x,y,plane,wave,boss,raid room,killing blow,biggest hit,damage last 10s,hits last 10s,prayer left,"
		+ "your combat level,carried gp,most valuable,note,source";

	private DeathCsv()
	{
	}

	static String of(List<Death> deaths)
	{
		SimpleDateFormat when = new SimpleDateFormat("yyyy-MM-dd HH:mm:ss");
		StringBuilder sb = new StringBuilder(HEADER).append('\n');
		int n = 0;
		for (Death d : deaths)
		{
			n++;
			StringBuilder top = new StringBuilder();
			for (String t : d.top)
			{
				int bar = t.lastIndexOf('|');
				top.append(top.length() > 0 ? "; " : "").append(bar < 0 ? t : t.substring(0, bar) + " " + t.substring(bar + 1));
			}
			Object[] row = {n, when.format(new Date(d.at)), d.world, d.killer, d.killerLevel, d.pvp ? "yes" : "",
				String.join("; ", d.others), d.cause, d.area, d.areaType, d.wildy > 0 ? d.wildy : "", d.x, d.y, d.plane,
				d.wave > 0 ? d.wave : "", d.boss, d.room(), d.lastHit, d.maxHit, d.damage, d.hits, d.prayer, d.combat, d.carried,
				top, d.note, d.from == null ? "recorded" : d.from};
			for (int i = 0; i < row.length; i++)
			{
				sb.append(i > 0 ? "," : "").append(cell(row[i]));
			}
			sb.append('\n');
		}
		return sb.toString();
	}

	/** A cell, quoted when it holds a comma, a quote or a line break; nothing for null. */
	static String cell(Object o)
	{
		String s = o == null ? "" : String.valueOf(o);
		return s.contains(",") || s.contains("\"") || s.contains("\n") ? "\"" + s.replace("\"", "\"\"") + "\"" : s;
	}
}

