import java.util.regex.Matcher;
import java.util.regex.Pattern;
import java.util.stream.Stream;
import net.runelite.client.util.Filepath;

/**
 * Deaths from before Death Log: RuneLite's own Screenshot plugin (its "Screenshot deaths" setting) saves each of your
 * deaths as screenshots/&lt;name&gt;/Deaths/"Death 2026-11-04_18-22-11.png" (local time; "(1)" added for a second one
 * in the same second). Friends' and clan members' deaths carry their name — "Death Zezima 2026-..." — and are left out.
 * Only the date is in a file name, so an imported death has nothing else.
 */
final class DeathImport
{
	static final String FROM_SCREENSHOT = "RuneLite screenshot";
	/** A death already in the log this close to a screenshot's time is the same death. */
	static final long SAME_MS = 120_000L;
	private static final Pattern OWN = Pattern.compile("^Death (\\d{4}-\\d{2}-\\d{2}_\\d{2}-\\d{2}-\\d{2})(?:\\(\\d+\\))?\\.png$");
	private static final DateTimeFormatter TIME = DateTimeFormatter.ofPattern("yyyy-MM-dd_HH-mm-ss");

	private DeathImport()
	{
	}

	/** How deep the import looks under the folder you pick: enough for .runelite/screenshots/&lt;name&gt;/Deaths/file. */
	static final int DEPTH = 4;
	/** {@link #classify}: not a death screenshot. */
	static final long NOT_ONE = -1;
	/** {@link #classify}: a death screenshot in another player's folder. */
	static final long SOMEONE_ELSE = -2;

	/**
	 * One file under the folder you picked, by its folders' names: {@code parts} = [the picked folder, ..., the file]
	 * (only names: RuneLite's file rules don't let a plugin look above the picked folder, so nothing here needs to).
	 * The picked folder can be .runelite, its screenshots folder, your name's folder, or its Deaths folder. Returns the
	 * screenshot's time (epoch ms), {@link #NOT_ONE} or {@link #SOMEONE_ELSE}.
	 */
	static long classify(List<String> parts, String me, ZoneId zone)
	{
		int n = parts.size();
		if (n < 2)
		{
			return NOT_ONE;                                   // the picked folder itself
		}
		long t = timeOf(parts.get(n - 1), zone);
		if (t < 0 || !"Deaths".equals(parts.get(n - 2)))
		{
			return NOT_ONE;
		}
		if (n - 3 <= 0)
		{
			return t;                                         // you picked a Deaths folder, or your name's folder
		}
		String owner = parts.get(n - 3);
		return me != null && me.equalsIgnoreCase(owner) ? t : SOMEONE_ELSE;
	}

	/**
	 * Every death screenshot of yours under the picked folder, into {@code out} (its time → the file; the first of a
	 * same-second pair). Returns how many were in other players' folders. Never looks above {@code root}: RuneLite's
	 * file rules forbid it (asking for the picked folder's parent threw "Path escaped its root" and the import died,
	 * 2026-11-08).
	 */
	static int find(Filepath root, String me, ZoneId zone, Map<Long, Filepath> out) throws IOException
	{
		int others = 0;
		try (Stream<Filepath> files = root.walk(DEPTH))
		{
			for (Filepath f : (Iterable<Filepath>) files::iterator)
			{
				if (f.equals(root))
				{
					continue;
				}
				LinkedList<String> parts = new LinkedList<>();
				for (Filepath p = f; p != null && !p.equals(root); p = p.getParent())
				{
					parts.addFirst(p.getFileName());
				}
				parts.addFirst(root.getFileName() == null ? "" : root.getFileName());
				long t = classify(parts, me, zone);
				if (t == SOMEONE_ELSE)
				{
					others++;
				}
				else if (t >= 0)
				{
					out.putIfAbsent(t, f);
				}
			}
		}
		return others;
	}

	/** When a screenshot of YOUR death was taken (epoch ms); -1 = not one. */
	static long timeOf(String fileName, ZoneId zone)
	{
		Matcher m = OWN.matcher(fileName);
		if (!m.matches())
		{
			return -1;
		}
		try
		{
			return LocalDateTime.parse(m.group(1), TIME).atZone(zone).toInstant().toEpochMilli();
		}
		catch (DateTimeParseException e)
		{
			return -1;
		}
	}

	/** The new deaths among {@code times} (epoch ms): none within {@link #SAME_MS} of one already known, or of each other. */
	static List<Death> fresh(List<Long> times, List<Death> known)
	{
		List<Long> taken = new ArrayList<>();
		for (Death d : known)
		{
			taken.add(d.at);
		}
		List<Long> sorted = new ArrayList<>(times);
		sorted.sort(null);
		List<Death> out = new ArrayList<>();
		for (long t : sorted)
		{
			boolean dup = false;
			for (long k : taken)
			{
				dup |= Math.abs(k - t) < SAME_MS;
			}
			if (!dup)
			{
				Death d = new Death();
				d.at = t;
				d.from = FROM_SCREENSHOT;
				out.add(d);
				taken.add(t);
			}
		}
		return out;
	}
}

