	/** The counters a death adds to. */
	enum Counter
	{
		OFF("Off"),
		LIFETIME("All time"),
		TODAY("Today"),
		SESSION("This session"),
		LAST_HOUR("Last hour"),
		TRIP_A("Counter 1"),
		TRIP_B("Counter 2");

		private final String label;

		Counter(String label)
		{
			this.label = label;
		}

		@Override
		public String toString()
		{
			return label;
		}
	}

	/** How the panel and the graphs look (Theme). */
	enum Look
	{
		DASHBOARD("Dashboard"),
		GRAVESTONE("Gravestone"),
		OLD_SCHOOL("Old School"),
		ECTOPLASM("Ectoplasm"),
		INFERNAL("Infernal"),
		PLAIN("Plain");

