		Look(String label)
		{
			this.label = label;
		}

		@Override
		public String toString()
		{
			return label;
		}
	}

	/** When Counter 1 / Counter 2 start again from 0 by themselves (their Reset button always works). */
	enum TripReset
	{
		NEVER("Only with Reset"),
		LOGIN("Each login"),
		DAILY("Each day");

		private final String label;

		TripReset(String label)
		{
			this.label = label;
		}

		@Override
		public String toString()
		{
			return label;
		}
	}

	@ConfigItem(
		position = -1,
		keyName = "look",
		name = "Look",
		description = "How the panel and the graphs look: Dashboard, Gravestone (your total on a tombstone), Old School "
			+ "(the game's own interface), Ectoplasm (ghostly), Infernal (lava), Plain (RuneLite's own)"
	)
	default Look look()
	{
		return Look.DASHBOARD;
	}

	@ConfigItem(
		position = 0,
		keyName = "counterBox",        // was "infoBox" until 2026-11-04: RuneLite had saved its old default (Counter 1)
		name = "Counter on screen",
		description = "One counter as a box on the game screen (off by default); hover it for all of them"
	)
	default Counter infoBox()
	{
		return Counter.OFF;            // user, 2026-11-04: "make this off by default ... i dont need more things there"
