	@ConfigItem(
		position = 1,
		keyName = "chatMessage",
		name = "Message after a death",
		description = "A line in your chat box after each death: what killed you, where, and your counters. Only you see it"
	)
	default boolean chatMessage()
	{
		return true;
	}

	@ConfigItem(
		position = 2,
		keyName = "streakMessage",
		name = "Kills since last death",
		description = "After each boss kill, a line in your chat box: how many kills of that boss since your last death "
			+ "to it, and your best run. Only you see it"
	)
	default boolean streakMessage()
	{
		return true;
	}

	@ConfigItem(
		position = 2,
		keyName = "mapMarkers",
		name = "Deaths on the world map",
		description = "A skull on the world map where you died; hover it for when and what killed you"
	)
	default boolean mapMarkers()
	{
		return true;
	}

	@ConfigItem(
		position = 2,
		keyName = "deathPictures",
		name = "Death screenshots",
		description = "Show RuneLite's screenshot of each death on its card (Death Log keeps its own copy). Needs the "
			+ "Screenshot plugin's \"Screenshot deaths\" setting on. Import adds the ones you already have."
