	{
		return 25;
	}

	@ConfigItem(
		position = 4,
		keyName = "tripAReset",
		name = "Counter 1 starts again",
		description = "When Counter 1 goes back to 0 by itself. Its Reset button in the panel always works; click its name there to rename it"
	)
