	@ConfigItem(
		position = 5,
		keyName = "tripBReset",
		name = "Counter 2 starts again",
		description = "When Counter 2 goes back to 0 by itself. Its Reset button in the panel always works; click its name there to rename it"
	)
	default TripReset tripBReset()
	{
		return TripReset.NEVER;
	}
