/**
 * The side panel, drawn in the chosen theme (Theme, the "Look" setting): the total, today / session / last hour,
 * Counter 1 and 2, kills since your last death, the last 14 days, bosses, killers, places and every death.
 */
final class DeathLogPanel extends PluginPanel
{
	private static final int PAD = 8;
	private static final int CW = PANEL_WIDTH - 2 * PAD;
	private static final int TOP = 8;
	private static final int RECENT = 40;
	private static final String WHEN = "EEE d MMM HH:mm";
	/** A death's picture on its card: this tall, the screenshot's middle filling the card's width. */
	private static final int PIC_H = 96;
	/** Pictures are read this wide for the cards (sharp on a 2x screen too). */
	private static final int THUMB_W = 480;

	private final DeathLogPlugin plugin;
	private Theme t;
	private final Timer timer;
	private StatsWindow stats;
	/** What the lists were built from: rebuilt only when it changes (the timer repaints the numbers). */
	private Object builtFrom;
	private Object builtKc;
	private int builtSize = -1;
	private DeathLogPlugin.View view;

	DeathLogPanel(DeathLogPlugin plugin, Theme theme)
	{
		this.plugin = plugin;
		this.t = theme;
		setLayout(new BoxLayout(this, BoxLayout.Y_AXIS));
		setBorder(new EmptyBorder(PAD, PAD, PAD, PAD));
		timer = new Timer(10_000, e -> refresh());
		timer.start();
		applyTheme(theme);
	}

	/**
	 * Death pictures read for the cards, by death time; a null value = asked, not back yet (Swing thread). The 30 used
	 * last are kept (about half a megabyte each); a card scrolled back to reads its picture again.
	 */
	private final Map<Long, BufferedImage> thumbs = new java.util.LinkedHashMap<Long, BufferedImage>(16, 0.75f, true)
	{
		@Override
		protected boolean removeEldestEntry(Map.Entry<Long, BufferedImage> eldest)
		{
			return size() > 30;
		}
	};
	private final Set<Long> unreadable = new HashSet<>();
	private JFrame viewer;

	void stop()
	{
		timer.stop();
		if (viewer != null)
		{
			viewer.dispose();
			viewer = null;
		}
		if (stats != null)
		{
			stats.dispose();
			stats = null;
		}
	}

	/** A new look: everything drawn again (Swing thread). */
	void applyTheme(Theme theme)
	{
		t = theme;
		setBackground(t.background);
		getWrappedPanel().setBackground(t.background);
		if (getScrollPane() != null)
		{
			getScrollPane().getViewport().setBackground(t.background);
		}
		if (stats != null)
		{
			stats.theme(t);
		}
		builtFrom = null;
		refresh();
	}

	/** Everything again (Swing thread). The lists are rebuilt only when the deaths or kill counts changed. */
	/** The pictures the cards were built with ({@link DeathLogPlugin#pictureGen()}). */
	private int builtPictures = -1;

	void refresh()
	{
		view = plugin.view();
		if (view.deaths != builtFrom || view.deaths.size() != builtSize || view.killCounts != builtKc
			|| plugin.pictureGen() != builtPictures)
		{
			builtFrom = view.deaths;
			builtSize = view.deaths.size();
			builtKc = view.killCounts;
			builtPictures = plugin.pictureGen();   // a new picture changes no death: without this its card stayed bare (11-08)
			build(view);
			if (stats != null && stats.isVisible())
			{
				stats.update(view);
			}
		}
		revalidate();
		repaint();
	}

	@Override
	protected void paintComponent(Graphics g0)
	{
		super.paintComponent(g0);
		if (t != null && t.blocks != null)
		{
			Graphics2D g = (Graphics2D) g0;
			g.setColor(t.blocks);
			for (int y = 0; y < getHeight(); y += 18)
			{
				for (int x = (y / 18) % 2 * 20 - 20; x < getWidth(); x += 40)
				{
					g.drawRect(x, y, 40, 18);
				}
			}
		}
	}

	private void build(DeathLogPlugin.View v)
	{
		removeAll();
		add(new HeroPart());
		gap(6);
		add(new ButtonPart("Statistics & graphs", "Deaths over time, each boss's kills between deaths, your waves at the "
			+ "Inferno, when and how you die", this::openStats));
		gap(6);
		if (!v.loaded)
		{
			add(new TextPart("Log in to see your deaths.", t.dim));
			gap(6);
		}
		add(new TilesPart());
		gap(6);
		add(new CounterPart(true));
		gap(4);
		add(new CounterPart(false));

		List<DeathStats.BossRow> rows = DeathStats.bosses(v.deaths, v.killCounts);
		List<DeathStats.BossRow> running = new ArrayList<>();
		for (DeathStats.BossRow r : rows)
		{
			if (r.sinceDeath >= 0)
			{
				running.add(r);
			}
		}
		running.sort((x, y) -> Integer.compare(y.sinceDeath, x.sinceDeath));
		if (!running.isEmpty())
		{
			add(new HeaderPart("Since your last death"));
			for (DeathStats.BossRow r : running.subList(0, Math.min(running.size(), 5)))
			{
				add(new StreakPart(r));
				gap(4);
			}
		}

		add(new HeaderPart("Last 14 days"));
		add(new DaysPart(DeathStats.perDay(v.deaths, v.now, 14, ZoneId.systemDefault())));

		if (section("bosses", "Bosses", rows.size()))
		{
			for (DeathStats.BossRow r : rows.subList(0, Math.min(rows.size(), 25)))
			{
				add(new BossPart(r));
				gap(3);
			}
			if (rows.isEmpty())
			{
				add(new TextPart("No boss deaths or kill counts yet.", t.dim));
			}
		}

		List<Map.Entry<String, Integer>> killers = DeathStats.top(v.deaths, d -> d.from != null ? null : d.killedBy(), TOP);
		if (section("killers", "What killed you", killers.size()))
		{
			for (Map.Entry<String, Integer> e : killers)
			{
				add(new ListPart(e.getKey(), e.getValue()));
				gap(3);
			}
			if (killers.isEmpty())
			{
				add(new TextPart("Nothing yet.", t.dim));
			}
		}

		List<Map.Entry<String, Integer>> places = DeathStats.top(v.deaths, d -> d.from != null ? null : d.area != null ? d.area
			: d.wildy > 0 ? "Wilderness" : "Unnamed area", TOP);
		if (section("places", "Where", places.size()))
		{
			for (Map.Entry<String, Integer> e : places)
			{
				add(new ListPart(e.getKey(), e.getValue()));
				gap(3);
			}
			if (places.isEmpty())
			{
				add(new TextPart("Nothing yet.", t.dim));
			}
		}

		if (section("deaths", "Every death", v.deaths.size()))
		{
			for (int i = v.deaths.size() - 1; i >= Math.max(0, v.deaths.size() - RECENT); i--)
			{
				add(new DeathPart(v.deaths.get(i), i + 1));
				gap(4);
			}
			if (v.deaths.isEmpty())
			{
				add(new TextPart("No deaths recorded yet.", t.dim));
			}
		}
		gap(8);
		add(new ButtonPart("Export to CSV", "Every death in a .csv file - opens in Excel, Google Sheets or LibreOffice",
			() -> plugin.exportCsv(this)));
		gap(4);
		add(new ButtonPart("Import old deaths", "<html>Pick your <b>.runelite</b> folder: Death Log reads RuneLite's death screenshots in it<br>"
			+ "(its Screenshot plugin, \"Screenshot deaths\" on): deaths from before Death Log (the date and time only),<br>"
			+ "and each screenshot as the picture on its death's card</html>",
			() -> plugin.importScreenshots(this)));
	}

	private void gap(int h)
	{
		add(new Gap(h));
	}

	/** A section header you click to open or close (remembered); true when it is open. */
	private boolean section(String key, String title, int count)
	{
		boolean on = plugin.isOpen(key);
		HeaderPart h = new HeaderPart(title);
		h.collapsible(key, on, count);
		add(h);
		return on;
	}

	private void openStats()
	{
		if (stats == null)
		{
			stats = new StatsWindow(plugin.icon());
			stats.setLocationRelativeTo(this);
		}
		stats.theme(t);
		stats.update(plugin.view());
		stats.setVisible(true);
		stats.toFront();
	}

	// ======================================================= the parts

	/** A part of the panel: as wide as the panel, a fixed height, drawn in the theme. */
	private abstract class Part extends JComponent
	{
		Part(int height)
		{
			setPreferredSize(new Dimension(CW, height));
			setMinimumSize(new Dimension(50, height));
			setMaximumSize(new Dimension(Integer.MAX_VALUE, height));
			setAlignmentX(LEFT_ALIGNMENT);
		}

		@Override
		protected final void paintComponent(Graphics g0)
		{
			Graphics2D g = (Graphics2D) g0.create();
			Draw.smooth(g);
			draw(g, getWidth(), getHeight());
			g.dispose();
		}

		abstract void draw(Graphics2D g, int w, int h);
	}

	private final class Gap extends Part
	{
		Gap(int h)
		{
			super(h);
		}

		@Override
		void draw(Graphics2D g, int w, int h)
		{
		}
	}

