	/** The top: the total and how long you have been alive, in the theme's style. */
	private final class HeroPart extends Part
	{
		HeroPart()
		{
			super(t.hero == Theme.Hero.TOMBSTONE ? 162 : t.hero == Theme.Hero.BEVEL ? 118 : 116);
		}

		@Override
		void draw(Graphics2D g, int w, int h)
		{
			int total = view.deaths.size();
			String alive = alive();
			if (t.hero == Theme.Hero.TOMBSTONE)
			{
				tombstone(g, w, total, alive);
			}
			else if (t.hero == Theme.Hero.BEVEL)
			{
				Draw.bevel(g, t, 0, 0, w, 26);
				g.setFont(Draw.bold());
				Draw.centre(g, t, "Death Log", w / 2, 18, t.title);
				Draw.skull(g, 7, 6, 14, new Color(0xE8, 0xE0, 0xC8));
				Draw.bevel(g, t, 0, 32, w, h - 32);
				g.setFont(Draw.bold().deriveFont(34f));
				Draw.centre(g, t, String.format("%,d", total), w / 2, 72, t.number());
				g.setFont(Draw.plain());
				Draw.centre(g, t, total == 1 ? "Death" : "Deaths", w / 2, 90, t.title);
				g.setFont(Draw.small());
				Draw.centre(g, t, Draw.fit(g.getFontMetrics(), alive, w - 12), w / 2, 108, Color.WHITE);
			}
			else
			{
				card(g, w, h, total, alive);
			}
		}

		private String alive()
		{
			if (view.deaths.isEmpty())
			{
				return view.loaded ? "no deaths yet" : "log in to start";
			}
			long last = view.deaths.get(view.deaths.size() - 1).at;
			return "alive " + DeathStats.duration(view.now - last) + " · best "
				+ DeathStats.duration(DeathStats.longestAlive(view.deaths, view.now));
		}

		private void card(Graphics2D g, int w, int h, int total, String alive)
		{
			RoundRectangle2D shape = new RoundRectangle2D.Double(0, 0, w - 1, h - 1, t.radius + 4, t.radius + 4);
			g.setPaint(new GradientPaint(0, 0, t.heroTop, w, h, t.heroBottom));
			if (t.lava)
			{
				Draw.lava(g, shape, w, h);
			}
			else if (t.card == Theme.Card.FLAT)
			{
				g.fillRect(0, 0, w, h);
			}
			else
			{
				g.fill(shape);
			}
			if (t.motes != null)
			{
				Draw.motes(g, t.motes, 6, 6, w - 12, h - 12);
			}
			if (t.cardEdge != null)
			{
				g.setColor(t.cardEdge);
				g.draw(shape);
			}
			Color soft = new Color(255, 255, 255, 215);
			Draw.skull(g, 10, 10, 14, soft);
			g.setFont(Draw.bold());
			Draw.text(g, t, "Death Log", 30, 22, t.title == Color.WHITE ? soft : t.title);
			g.setFont(Draw.bold().deriveFont(38f));
			String n = String.format("%,d", total);
			Draw.number(g, t, n, 10, 66, t.number());
			int nw = g.getFontMetrics().stringWidth(n);
			g.setFont(Draw.small());
			Draw.text(g, t, total == 1 ? "death all time" : "deaths all time", 10, 82, new Color(255, 255, 255, 170));
			// the last 14 days as a line
			int[] days = DeathStats.perDay(view.deaths, view.now, 14, ZoneId.systemDefault());
			int lx = Math.max(100, 10 + nw + 14);
			int lw = w - lx - 10;
			int ly = 36;
			int lh = 40;
			int max = 1;
			for (int d : days)
			{
				max = Math.max(max, d);
			}
			Path2D line = new Path2D.Double();
			for (int i = 0; i < days.length; i++)
			{
				double px = lx + (double) lw * i / (days.length - 1);
				double py = ly + lh - (double) lh * days[i] / max;
				if (i == 0)
				{
					line.moveTo(px, py);
				}
				else
				{
					line.lineTo(px, py);
				}
			}
			Color stroke = t.glow != null ? t.glow : new Color(255, 255, 255, 210);
			g.setStroke(new BasicStroke(2f, BasicStroke.CAP_ROUND, BasicStroke.JOIN_ROUND));
			g.setColor(stroke);
			g.draw(line);
			g.setStroke(new BasicStroke(1f));
			g.fillOval(lx + lw - 3, ly + lh - lh * days[days.length - 1] / max - 3, 6, 6);
			Draw.right(g, t, "14 days", lx + lw, ly + lh + 12, new Color(255, 255, 255, 150));
			Draw.chip(g, t, 10, 90, Draw.fit(g.getFontMetrics(), alive, w - 32), new Color(255, 255, 255, 220));
		}

		private void tombstone(Graphics2D g, int w, int total, String alive)
		{
			g.setFont(Draw.bold());
			Draw.text(g, t, "DEATH LOG", 2, 14, t.title);
			Draw.skull(g, w - 18, 2, 14, new Color(0xD8, 0xD0, 0xBC));
			int sx = 32;
			int sy = 22;
			int sw = w - 64;
			int sh = 126;
			Path2D tomb = Draw.tombstone(sx, sy, sw, sh);
			g.setPaint(new GradientPaint(sx, sy, t.heroTop, sx + sw, sy + sh, t.heroBottom));
			g.fill(tomb);
			g.setColor(new Color(0x2A, 0x2B, 0x2E));
			g.setStroke(new BasicStroke(2f));
			g.draw(tomb);
			g.setStroke(new BasicStroke(1f));
			g.setColor(new Color(0x4A, 0x4C, 0x50));
			g.drawLine(sx + sw - 22, sy + 30, sx + sw - 30, sy + 46);
			g.drawLine(sx + sw - 30, sy + 46, sx + sw - 26, sy + 58);
			Color deep = new Color(0x18, 0x19, 0x1B);
			Color lit = new Color(0xB4, 0xB6, 0xBA);
			g.setFont(Draw.bold());
			Draw.carved(g, "HERE LIE", w / 2, sy + 32, deep, lit);
			g.setFont(Draw.bold().deriveFont(total >= 1000 ? 32f : 44f));
			Draw.carved(g, String.format("%,d", total), w / 2, sy + 80, deep, lit);
			g.setFont(Draw.bold());
			Draw.carved(g, total == 1 ? "DEATH" : "DEATHS", w / 2, sy + 96, deep, lit);
			g.setFont(Draw.small());
			Draw.carved(g, Draw.fit(g.getFontMetrics(), alive, sw - 16), w / 2, sy + 110, new Color(0x2A, 0x2B, 0x2E), lit);
			g.setColor(new Color(0x3A, 0x2C, 0x22));
			g.fillRoundRect(6, sy + sh - 2, w - 12, 14, 14, 14);
			g.setColor(t.good);
			for (int x = 12; x < w - 12; x += 7)
			{
				g.drawLine(x, sy + sh, x + 2, sy + sh - 5);
			}
		}
	}

	/** A themed button. */
	private final class ButtonPart extends Part
	{
		private final String text;
		private boolean over;

		ButtonPart(String text, String tip, Runnable action)
		{
			super(26);
			this.text = text;
			setToolTipText(tip);
			setCursor(Cursor.getPredefinedCursor(Cursor.HAND_CURSOR));
			addMouseListener(new MouseAdapter()
			{
				@Override
				public void mouseClicked(MouseEvent e)
				{
					action.run();
				}

				@Override
				public void mouseEntered(MouseEvent e)
				{
					over = true;
					repaint();
				}

				@Override
				public void mouseExited(MouseEvent e)
				{
					over = false;
					repaint();
				}
			});
		}

		@Override
		void draw(Graphics2D g, int w, int h)
		{
			if (t.card == Theme.Card.BEVEL)
			{
				g.setPaint(new GradientPaint(0, 0, over ? new Color(0x6A, 0x5A, 0x42) : new Color(0x5A, 0x4C, 0x38), 0, h,
					new Color(0x3A, 0x30, 0x24)));
				g.fillRect(0, 0, w, h);
				g.setColor(t.bevelLight.brighter());
				g.drawLine(0, 0, w - 1, 0);
				g.drawLine(0, 0, 0, h - 1);
				g.setColor(t.bevelDark);
				g.drawLine(0, h - 1, w - 1, h - 1);
				g.drawLine(w - 1, 0, w - 1, h - 1);
			}
			else
			{
				g.setColor(over ? t.chip.brighter() : t.chip);
				if (t.card == Theme.Card.FLAT)
				{
					g.fillRect(0, 0, w, h);
				}
				else
				{
					g.fill(new RoundRectangle2D.Double(0, 0, w - 1, h - 1, t.radius, t.radius));
				}
				if (t.cardEdge != null || over)
				{
					g.setColor(over ? t.accent : t.cardEdge);
					g.draw(new RoundRectangle2D.Double(0.5, 0.5, w - 2, h - 2, t.radius, t.radius));
				}
			}
			g.setFont(Draw.bold());
			Draw.centre(g, t, text, w / 2, h / 2 + 5, t.card == Theme.Card.BEVEL ? t.title : t.text);
		}
	}

	/** Today, this session, the last hour. */
	private final class TilesPart extends Part
	{
		TilesPart()
		{
			super(50);
		}

		@Override
		void draw(Graphics2D g, int w, int h)
		{
			int[] n = {DeathLogPlugin.count(view, DeathLogConfig.Counter.TODAY),
				DeathLogPlugin.count(view, DeathLogConfig.Counter.SESSION),
				DeathLogPlugin.count(view, DeathLogConfig.Counter.LAST_HOUR)};
			String[] names = {"Today", "Session", "Last hour"};
			int tw = (w - 8) / 3;
			for (int i = 0; i < 3; i++)
			{
				int x = i * (tw + 4);
				Draw.card(g, t, x, 0, tw, h);
				if (t.tileStripes != null)
				{
					g.setColor(t.tileStripes[i]);
					g.fill(new RoundRectangle2D.Double(x, 0, tw - 1, 4, 4, 4));
				}
				g.setFont(Draw.bold().deriveFont(20f));
				String s = String.valueOf(n[i]);
				Color c = n[i] > 0 && t.tileStripes == null ? t.accent : t.number();
				if (t.card == Theme.Card.BEVEL || t.hero == Theme.Hero.TOMBSTONE)
				{
					Draw.centre(g, t, s, x + tw / 2, 26, c);
					g.setFont(Draw.small());
					Draw.centre(g, t, t.upperCaseHeaders ? names[i].toUpperCase() : names[i], x + tw / 2, 41,
						t.card == Theme.Card.BEVEL ? t.title : t.dim);
				}
				else
				{
					Draw.number(g, t, s, x + 8, 28, c);
					g.setFont(Draw.small());
					Draw.text(g, t, names[i], x + 8, 43, t.dim);
				}
			}
		}
	}

	/** Counter 1 / Counter 2: like a car's trip odometer — counts from its Reset. Click its name to rename it. */
	private final class CounterPart extends Part
	{
		private final boolean a;
		private final Rectangle reset = new Rectangle();
		private final Rectangle name = new Rectangle();

		CounterPart(boolean a)
		{
			super(50);
			this.a = a;
			setToolTipText("Click the name to rename it · Reset starts it again from 0");
			addMouseListener(new MouseAdapter()
			{
				@Override
				public void mouseClicked(MouseEvent e)
				{
					String n = a ? view.tripAName : view.tripBName;
					if (reset.contains(e.getPoint()))
					{
						if (JOptionPane.showConfirmDialog(DeathLogPanel.this, "Start " + n + " again from 0?", "Reset " + n,
							JOptionPane.OK_CANCEL_OPTION) == JOptionPane.OK_OPTION)
						{
							plugin.resetTrip(a);
						}
					}
					else if (name.contains(e.getPoint()))
					{
						Object typed = JOptionPane.showInputDialog(DeathLogPanel.this,
							"Name this counter (for example \"Inferno practice\"):", "Rename " + n, JOptionPane.PLAIN_MESSAGE,
							null, null, n);
						if (typed != null)
						{
							plugin.renameTrip(a, typed.toString());
						}
					}
				}
			});
			addMouseMotionListener(new MouseAdapter()
			{
				@Override
				public void mouseMoved(MouseEvent e)
				{
					setCursor(Cursor.getPredefinedCursor(reset.contains(e.getPoint()) || name.contains(e.getPoint())
						? Cursor.HAND_CURSOR : Cursor.DEFAULT_CURSOR));
				}
			});
		}

		@Override
		void draw(Graphics2D g, int w, int h)
		{
			String n = a ? view.tripAName : view.tripBName;
			long since = a ? view.tripA : view.tripB;
			int count = DeathLogPlugin.count(view, a ? DeathLogConfig.Counter.TRIP_A : DeathLogConfig.Counter.TRIP_B);
			long ms = view.now - since;
			double rate = DeathStats.perHour(count, ms);
			Draw.card(g, t, 0, 0, w, h);
			boolean bevel = t.card == Theme.Card.BEVEL;
			int bw = bevel ? 42 : 24;
			reset.setBounds(w - bw - 8, bevel ? 13 : 12, bw, bevel ? 22 : 24);
			g.setFont(Draw.bold().deriveFont(24f));
			String c = String.valueOf(count);
			int right = reset.x - 6;
			Draw.number(g, t, c, right - g.getFontMetrics().stringWidth(c), 32,
				count > 0 ? (bevel ? t.number() : t.accent) : t.number());
			int textRight = right - g.getFontMetrics().stringWidth(c) - 6;
			g.setFont(Draw.bold());
			String shown = Draw.fit(g.getFontMetrics(), n, textRight - 10);
			Draw.text(g, t, shown, 10, 19, bevel ? t.title : t.text);
			name.setBounds(6, 4, g.getFontMetrics().stringWidth(shown) + 8, 20);
			if (t.card == Theme.Card.ROUND)
			{
				int x = 10;
				x += Draw.chip(g, t, x, 27, DeathStats.duration(ms), t.dim) + 4;
				if (rate > 0)
				{
					Draw.chip(g, t, x, 27, String.format("%.1f/h", rate), t.dim);
				}
			}
			else
			{
				g.setFont(Draw.small());
				String line = DeathStats.duration(ms) + " · since " + new SimpleDateFormat("HH:mm").format(new Date(since))
					+ (rate > 0 ? String.format(" · %.1f/h", rate) : "");
				Draw.text(g, t, Draw.fit(g.getFontMetrics(), line, textRight - 10), 10, 36, t.dim);
			}
			if (bevel)
			{
				g.setPaint(new GradientPaint(reset.x, reset.y, new Color(0x5A, 0x4C, 0x38), reset.x, reset.y + reset.height,
					new Color(0x3A, 0x30, 0x24)));
				g.fillRect(reset.x, reset.y, reset.width, reset.height);
				g.setColor(t.bevelLight.brighter());
				g.drawLine(reset.x, reset.y, reset.x + reset.width - 1, reset.y);
				g.drawLine(reset.x, reset.y, reset.x, reset.y + reset.height - 1);
				g.setColor(t.bevelDark);
				g.drawLine(reset.x, reset.y + reset.height - 1, reset.x + reset.width - 1, reset.y + reset.height - 1);
				g.drawLine(reset.x + reset.width - 1, reset.y, reset.x + reset.width - 1, reset.y + reset.height - 1);
				g.setFont(Draw.small());
				Draw.centre(g, t, "Reset", reset.x + reset.width / 2, reset.y + 15, t.title);
			}
			else
			{
				g.setColor(t.chip);
				if (t.card == Theme.Card.ROUND)
				{
					g.fillOval(reset.x, reset.y, reset.width, reset.height);
				}
				else
				{
					g.fillRoundRect(reset.x, reset.y, reset.width, reset.height, 6, 6);
				}
				resetArrow(g, reset.x + reset.width / 2, reset.y + reset.height / 2, t.dim);
			}
		}

		/** A circular "start again" arrow. */
		private void resetArrow(Graphics2D g, int cx, int cy, Color c)
		{
			g.setColor(c);
			g.setStroke(new BasicStroke(1.6f, BasicStroke.CAP_ROUND, BasicStroke.JOIN_ROUND));
			g.drawArc(cx - 6, cy - 6, 12, 12, 60, 280);
			Path2D head = new Path2D.Double();
			head.moveTo(cx + 3, cy - 9);
			head.lineTo(cx + 7, cy - 5);
			head.lineTo(cx + 2, cy - 3);
			head.closePath();
			g.fill(head);
			g.setStroke(new BasicStroke(1f));
		}
	}

	/** A section title in the theme's style; a collapsible one has an arrow and a count, and opens on a click. */
	private final class HeaderPart extends Part
	{
		private final String text;
		/** -1 = not collapsible. */
		private int count = -1;
		private boolean on = true;

		HeaderPart(String text)
		{
			super(26);
			this.text = text;
		}

		void collapsible(String key, boolean open, int n)
		{
			count = n;
			on = open;
			setCursor(Cursor.getPredefinedCursor(Cursor.HAND_CURSOR));
			setToolTipText(open ? "Click to close" : "Click to open");
			addMouseListener(new MouseAdapter()
			{
				@Override
				public void mouseClicked(MouseEvent e)
				{
					plugin.setOpen(key, !on);
					builtFrom = null;
					refresh();
				}
			});
		}

		@Override
		void draw(Graphics2D g, int w, int h)
		{
			g.setFont(Draw.bold());
			String s = (t.upperCaseHeaders ? text.toUpperCase() : text) + (count >= 0 ? " (" + count + ")" : "");
			if (count >= 0)
			{
				// the arrow: right when closed, down when open
				int ax = w - 10;
				int ay = h - 13;
				Path2D tri = new Path2D.Double();
				if (on)
				{
					tri.moveTo(ax - 4, ay - 2);
					tri.lineTo(ax + 4, ay - 2);
					tri.lineTo(ax, ay + 3);
				}
				else
				{
					tri.moveTo(ax - 2, ay - 4);
					tri.lineTo(ax + 3, ay);
					tri.lineTo(ax - 2, ay + 4);
				}
				tri.closePath();
				g.setColor(t.title);
				g.fill(tri);
				w -= 18;                               // the line stops before the arrow
			}
			int y = h - 8;
			FontMetrics fm = g.getFontMetrics();
			if (t.header == Theme.Header.CENTRED)
			{
				int x = w / 2 - fm.stringWidth(s) / 2;
				g.setColor(t.bevelDark);
				g.drawLine(4, y - 4, x - 6, y - 4);
				g.drawLine(x + fm.stringWidth(s) + 6, y - 4, w - 4, y - 4);
				g.setColor(t.bevelLight);
				g.drawLine(4, y - 3, x - 6, y - 3);
				g.drawLine(x + fm.stringWidth(s) + 6, y - 3, w - 4, y - 3);
				Draw.text(g, t, s, x, y, t.title);
				return;
			}
			int x = 2;
			if (t.header == Theme.Header.SKULL_LINE)
			{
				Draw.skull(g, x, y - 10, 10, t.accent);
				x += 15;
			}
			Draw.text(g, t, s, x, y, t.title);
			int end = x + fm.stringWidth(s) + 6;
			g.setColor(t.accent);
			g.drawLine(end, y - 4, w - 2, y - 4);
		}
	}

	/** One boss's run: kills since your last death to it, against your best. */
	private final class StreakPart extends Part
	{
		private final DeathStats.BossRow r;

		StreakPart(DeathStats.BossRow r)
		{
			super(38);
			this.r = r;
			setToolTipText("Like a \"days without an accident\" sign: kills of this boss since you last died to it. "
				+ "Best: the most kills in a row between two deaths.");
		}

		@Override
		void draw(Graphics2D g, int w, int h)
		{
			Draw.card(g, t, 0, 0, w, h);
			boolean best = r.deaths > 0 && r.sinceDeath > 0 && r.sinceDeath >= r.bestRun;
			g.setFont(Draw.bold());
			String num = String.valueOf(r.sinceDeath);
			int nw = g.getFontMetrics().stringWidth(num);
			Draw.number(g, t, num, w - 8 - nw, 15, best || r.deaths == 0 ? t.good : t.number());
			g.setFont(Draw.small());
			Draw.text(g, t, Draw.fit(g.getFontMetrics(), Bosses.display(r.boss), w - 24 - nw), 8, 14, t.text);
			Draw.bar(g, t, 8, 21, w - 16, 5, r.bestRun <= 0 ? (r.deaths == 0 ? 1 : 0) : (double) r.sinceDeath / r.bestRun, t.good);
			String note = r.deaths == 0 ? "no deaths yet" : best ? "your best run" : "best " + r.bestRun;
			Draw.right(g, t, note, w - 8, 35, t.card == Theme.Card.BEVEL ? t.title : t.dim);
		}
	}

	/** Deaths a day, the last 14 days (today on the right). */
	private final class DaysPart extends Part
	{
		private final int[] days;

		DaysPart(int[] days)
		{
			super(58);
			this.days = days;
			int sum = 0;
			for (int d : days)
			{
				sum += d;
			}
			setToolTipText(sum + " deaths in the last 14 days · today " + days[days.length - 1]);
		}

		@Override
		void draw(Graphics2D g, int w, int h)
		{
			Draw.card(g, t, 0, 0, w, h);
			int max = 1;
			for (int d : days)
			{
				max = Math.max(max, d);
			}
			int n = days.length;
			int bw = (w - 12) / n;
			g.setFont(Draw.small());
			for (int i = 0; i < n; i++)
			{
				int bh = days[i] == 0 ? 2 : (h - 24) * days[i] / max;
				int x = 6 + i * bw + 1;
				g.setColor(days[i] == 0 ? new Color(255, 255, 255, 25) : i == n - 1 ? t.accent : t.bar);
				if (t.card == Theme.Card.ROUND)
				{
					g.fill(new RoundRectangle2D.Double(x, h - 8 - bh, bw - 3, bh, 3, 3));
				}
				else
				{
					g.fillRect(x, h - 8 - bh, bw - 3, bh);
				}
				if (days[i] > 0)
				{
					Draw.centre(g, t, String.valueOf(days[i]), x + (bw - 3) / 2, h - 10 - bh, t.text);
				}
			}
		}
	}

