	/** One death: when, what, where, the damage before it; right-click to copy, note or delete. */
	private final class DeathPart extends Part
	{
		private final Death d;
		private final int number;
		private final boolean pic;
		/** Where the picture starts on the card, once drawn; -1 = no picture. */
		private int picTop = -1;

		DeathPart(Death d, int number)
		{
			super(height(d) + (plugin.hasPicture(d) ? PIC_H + 10 : 0));
			this.d = d;
			this.number = number;
			this.pic = plugin.hasPicture(d);
			setToolTipText(tooltip(d, pic));
			MouseAdapter mouse = new MouseAdapter()
			{
				@Override
				public void mouseClicked(MouseEvent e)
				{
					if (pic && picTop >= 0 && e.getY() >= picTop && SwingUtilities.isLeftMouseButton(e))
					{
						showBig(d, number);
					}
				}

				@Override
				public void mouseMoved(MouseEvent e)
				{
					boolean over = pic && picTop >= 0 && e.getY() >= picTop;
					setCursor(Cursor.getPredefinedCursor(over ? Cursor.HAND_CURSOR : Cursor.DEFAULT_CURSOR));
				}

				@Override
				public void mousePressed(MouseEvent e)
				{
					menu(e, d, number);
				}

				@Override
				public void mouseReleased(MouseEvent e)
				{
					menu(e, d, number);
				}
			};
			addMouseListener(mouse);
			addMouseMotionListener(mouse);   // the hand shows over the picture only
		}

		@Override
		void draw(Graphics2D g, int w, int h)
		{
			Draw.card(g, t, 0, 0, w, h);
			g.setColor(d.boss != null ? t.accent : t.chip.brighter());
			g.fillRect(t.card == Theme.Card.BEVEL ? 2 : 0, 6, 3, h - 12);
			boolean bevel = t.card == Theme.Card.BEVEL;
			int x = 10;
			int tw = w - x - 8;
			g.setFont(Draw.small());
			FontMetrics fm = g.getFontMetrics();
			String head = "#" + number + " · " + new SimpleDateFormat(WHEN).format(new Date(d.at))
				+ (d.world > 0 ? " · W" + d.world : "");
			Draw.text(g, t, Draw.fit(fm, head, tw), x, 14, bevel ? t.title : t.dim);
			g.setFont(Draw.bold());
			Draw.text(g, t, Draw.fit(g.getFontMetrics(), d.killedBy(), tw), x, 30, bevel ? t.number() : t.text);
			g.setFont(Draw.small());
			int y = 44;
			Draw.text(g, t, Draw.fit(fm, d.place(), tw), x, y, t.text);
			if (d.from == null)
			{
				y += 14;
				if (t.card == Theme.Card.ROUND)
				{
					int cx = x;
					if (d.hits > 0)
					{
						cx += Draw.chip(g, t, cx, y - 11, "took " + d.damage, t.dim) + 3;
						cx += Draw.chip(g, t, cx, y - 11, "max " + d.maxHit, t.dim) + 3;
					}
					cx += Draw.chip(g, t, cx, y - 11, "pray " + d.prayer, t.dim) + 3;
					if (d.carried > 0 && cx < w - 44)
					{
						Draw.chip(g, t, cx, y - 11, gp(d.carried), t.dim);
					}
				}
				else
				{
					String s = (d.hits > 0 ? "took " + d.damage + " in 10s · biggest " + d.maxHit + " · " : "") + "prayer "
						+ d.prayer + (d.carried > 0 ? " · " + gp(d.carried) : "");
					Draw.text(g, t, Draw.fit(fm, s, tw), x, y, t.dim);
				}
			}
			if (!d.others.isEmpty())
			{
				y += 14;
				Draw.text(g, t, Draw.fit(fm, "also: " + String.join(", ", d.others), tw), x, y, t.dim);
			}
			if (d.note != null)
			{
				y += 14;
				Draw.text(g, t, Draw.fit(fm, "note: " + d.note, tw), x, y, new Color(0xFF, 0xD0, 0x60));
			}
			if (pic)
			{
				picTop = h - PIC_H - 8;
				drawPicture(g, x, picTop, tw, PIC_H);
			}
		}

		/** The picture: its middle, filling the box; asked for once, drawn when it comes back. */
		private void drawPicture(Graphics2D g, int x, int y, int w, int h)
		{
			BufferedImage img = thumbs.get(d.at);
			if (img == null)
			{
				g.setColor(t.chip);
				g.fillRect(x, y, w, h);
				g.setFont(Draw.small());
				String say = unreadable.contains(d.at) ? "Can't open this picture" : "Loading picture...";
				Draw.text(g, t, say, x + (w - g.getFontMetrics().stringWidth(say)) / 2, y + h / 2 + 4, t.dim);
				if (!thumbs.containsKey(d.at) && !unreadable.contains(d.at))
				{
					thumbs.put(d.at, null);
					plugin.picture(d, THUMB_W, read ->
					{
						if (read == null)
						{
							thumbs.remove(d.at);
							unreadable.add(d.at);
						}
						else
						{
							thumbs.put(d.at, read);
						}
						repaint();
					});
				}
				return;
			}
			// the source's middle at the box's shape, so nothing is squashed
			double box = w / (double) h, src = img.getWidth() / (double) img.getHeight();
			int sw = img.getWidth(), sh = img.getHeight(), sx = 0, sy = 0;
			if (src > box)
			{
				sw = (int) Math.round(sh * box);
				sx = (img.getWidth() - sw) / 2;
			}
			else
			{
				sh = (int) Math.round(sw / box);
				sy = (img.getHeight() - sh) / 2;
			}
			java.awt.Shape clip = g.getClip();
			g.clip(new RoundRectangle2D.Float(x, y, w, h, 6, 6));
			g.setRenderingHint(java.awt.RenderingHints.KEY_INTERPOLATION, java.awt.RenderingHints.VALUE_INTERPOLATION_BILINEAR);
			g.drawImage(img, x, y, x + w, y + h, sx, sy, sx + sw, sy + sh, null);
			g.setClip(clip);
		}
	}

	/** A death's picture as big as the screen allows, in its own window (one window, reused). */
	private void showBig(Death d, int number)
	{
		plugin.picture(d, 0, img ->
		{
			if (img == null)
			{
				JOptionPane.showMessageDialog(this, "That picture can't be opened.", "Death Log", JOptionPane.WARNING_MESSAGE);
				return;
			}
			if (viewer == null)
			{
				viewer = new JFrame();
				viewer.setDefaultCloseOperation(WindowConstants.HIDE_ON_CLOSE);
				viewer.getRootPane().registerKeyboardAction(e -> viewer.setVisible(false),
					KeyStroke.getKeyStroke(java.awt.event.KeyEvent.VK_ESCAPE, 0), JComponent.WHEN_IN_FOCUSED_WINDOW);
			}
			viewer.setTitle("Death #" + number + " · " + new SimpleDateFormat(WHEN).format(new Date(d.at)) + " · " + d.killedBy());
			BigPicture big = new BigPicture(img);
			Rectangle screen = getGraphicsConfiguration() != null ? getGraphicsConfiguration().getBounds() : new Rectangle(0, 0, 1280, 800);
			double k = Math.min(1.0, Math.min(screen.width * 0.75 / img.getWidth(), screen.height * 0.75 / img.getHeight()));
			big.setPreferredSize(new Dimension((int) (img.getWidth() * k), (int) (img.getHeight() * k)));
			viewer.setContentPane(big);
			viewer.pack();
			viewer.setLocationRelativeTo(this);
			viewer.setVisible(true);
			viewer.toFront();
		});
	}

	/** A picture scaled to fit its window, never past its own size, on black. */
	private static final class BigPicture extends JComponent
	{
		private final BufferedImage img;

		BigPicture(BufferedImage img)
		{
			this.img = img;
		}

		@Override
		protected void paintComponent(Graphics g0)
		{
			Graphics2D g = (Graphics2D) g0;
			g.setColor(Color.BLACK);
			g.fillRect(0, 0, getWidth(), getHeight());
			double k = Math.min(1.0, Math.min(getWidth() / (double) img.getWidth(), getHeight() / (double) img.getHeight()));
			int w = (int) Math.round(img.getWidth() * k), h = (int) Math.round(img.getHeight() * k);
			g.setRenderingHint(java.awt.RenderingHints.KEY_INTERPOLATION, java.awt.RenderingHints.VALUE_INTERPOLATION_BILINEAR);
			g.drawImage(img, (getWidth() - w) / 2, (getHeight() - h) / 2, w, h, null);
		}
	}

	/** A death's height: its lines. */
	private static int height(Death d)
	{
		return 52 + (d.from == null ? 14 : 0) + (d.others.isEmpty() ? 0 : 14) + (d.note == null ? 0 : 14);
	}

	private void menu(MouseEvent e, Death d, int number)
	{
		if (!e.isPopupTrigger())
		{
			return;
		}
		JPopupMenu m = new JPopupMenu();
		JMenuItem copy = new JMenuItem("Copy");
		copy.addActionListener(ev -> Toolkit.getDefaultToolkit().getSystemClipboard()
			.setContents(new StringSelection(text(d, number)), null));
		m.add(copy);
		JMenuItem note = new JMenuItem(d.note == null ? "Add a note..." : "Edit the note...");
		note.addActionListener(ev ->
		{
			Object typed = JOptionPane.showInputDialog(this, "A note for death #" + number + " (for example \"lagged\"):",
				"Note", JOptionPane.PLAIN_MESSAGE, null, null, d.note == null ? "" : d.note);
			if (typed != null)
			{
				plugin.setNote(d, typed.toString());
			}
		});
		m.add(note);
		JMenuItem delete = new JMenuItem("Delete this death...");
		delete.addActionListener(ev ->
		{
			if (JOptionPane.showConfirmDialog(this, "Delete death #" + number + " (" + d.killedBy() + ") from the log?",
				"Delete a death", JOptionPane.OK_CANCEL_OPTION) == JOptionPane.OK_OPTION)
			{
				plugin.delete(d);
			}
		});
		m.add(delete);
		m.show(e.getComponent(), e.getX(), e.getY());
	}

	/** A death as plain text (Copy). */
	static String text(Death d, int number)
	{
		StringBuilder s = new StringBuilder("Death #" + number + " - " + new SimpleDateFormat(WHEN).format(new Date(d.at))
			+ " - world " + d.world + "\nKilled by: " + d.killedBy()
			+ (d.killerNote() == null ? "" : " (" + d.killerNote().replace("\n", " ") + ")") + "\nWhere: " + d.place()
			+ " (" + d.x + ", " + d.y + ", " + d.plane + ")");
		if (d.boss != null)
		{
			s.append("\nBoss: ").append(d.boss);
		}
		if (!d.others.isEmpty())
		{
			s.append("\nAlso attacking: ").append(String.join(", ", d.others));
		}
		s.append("\nLast 10 seconds: ").append(d.damage).append(" damage in ").append(d.hits).append(" hits, biggest ")
			.append(d.maxHit).append(", killing blow ").append(d.lastHit);
		s.append("\nPrayer left: ").append(d.prayer).append(" · your combat level ").append(d.combat);
		if (d.carried > 0)
		{
			s.append("\nCarried: ").append(gp(d.carried));
			for (String it : d.top)
			{
				int bar = it.lastIndexOf('|');
				s.append(bar < 0 ? "" : "\n  " + it.substring(0, bar) + " " + gp(Long.parseLong(it.substring(bar + 1))));
			}
		}
		if (d.note != null)
		{
			s.append("\nNote: ").append(d.note);
		}
		return s.toString();
	}

	private static String tooltip(Death d, boolean pic)
	{
		StringBuilder s = new StringBuilder("<html>");
		if (d.killerNote() != null)
		{
			s.append("<i>").append(esc(d.killerNote()).replace("\n", "<br>")).append("</i><br>");
		}
		if (d.boss != null)
		{
			s.append("Boss: ").append(esc(d.boss)).append("<br>");
		}
		s.append("Killing blow: ").append(d.lastHit).append(d.cause != null ? " (" + d.cause + ")" : "");
		if (d.carried > 0)
		{
			s.append("<br>Most valuable carried:");
			for (String it : d.top)
			{
				int bar = it.lastIndexOf('|');
				if (bar > 0)
				{
					s.append("<br>&nbsp;&nbsp;").append(esc(it.substring(0, bar))).append(" ")
						.append(gp(Long.parseLong(it.substring(bar + 1))));
				}
			}
		}
		return s.append(pic ? "<br>Click the picture to see it big" : "").append("<br>Right-click: copy, add a note, or delete</html>").toString();
	}

	private static String esc(String s)
	{
		return s.replace("&", "&amp;").replace("<", "&lt;").replace(">", "&gt;");
	}

	/** 85.2m / 1.20b / 12k / 950. */
	static String gp(long n)
	{
		return n >= 1_000_000_000L ? String.format("%.2fb", n / 1e9) : n >= 1_000_000L ? String.format("%.1fm", n / 1e6)
			: n >= 10_000L ? String.format("%.0fk", n / 1e3) : String.format("%,d", n);
	}
}

