	protected void startUp()
	{
		areas = Areas.load();
		skull = ImageUtil.loadImageResource(DeathLogPlugin.class, "skull.png");
		mapSkull = ImageUtil.resizeImage(skull, 16, 16);
		sessionStart = System.currentTimeMillis();
