	@Override
	protected void shutDown()
	{
		if (watch != null)
		{
			eventBus.unregister(watch);
			watch = null;
		}
		namer = null;
		clientToolbar.removeNavigation(navButton);
		panel.stop();
		if (infoBox != null)
		{
			infoBoxManager.removeInfoBox(infoBox);
			infoBox = null;
		}
		worldMapPointManager.removeIf(DeathPoint.class::isInstance);
		attackers.clear();
		hits.clear();
		deaths = List.of();
		killCounts = Map.of();
		profile = null;
		loggedIn = false;
		pictured.clear();
