	// ---- the game ----

	@Subscribe
	public void onGameStateChanged(GameStateChanged e)
	{
		GameState s = e.getGameState();
		if (s == GameState.LOGIN_SCREEN || s == GameState.CONNECTION_LOST)
		{
			loggedIn = false;
		}
		else if (s == GameState.LOGGED_IN && !loggedIn)
		{
			loggedIn = true;
			sessionStart = System.currentTimeMillis();
			loginResetsDue = true;
			attackers.clear();
			hits.clear();
		}
	}

	@Subscribe
	public void onGameTick(GameTick e)
	{
		checkProfile();
		Player me = client.getLocalPlayer();
		playerName = me == null ? playerName : me.getName();
		int tick = client.getTickCount();
		for (Iterator<Map.Entry<Actor, Attackers.Attacker>> it = attackers.entrySet().iterator(); it.hasNext(); )
		{
			Map.Entry<Actor, Attackers.Attacker> a = it.next();
			if (me != null && a.getKey().getInteracting() == me)
			{
				a.getValue().lastTick = tick;
			}
			else if (tick - a.getValue().lastTick > 100)
			{
				it.remove();
			}
		}
		while (!hits.isEmpty() && tick - hits.peekFirst()[0] > Attackers.WINDOW_TICKS)
		{
			hits.removeFirst();
		}
		if (tick % 50 == 0)
		{
			dailyResets();
		}
		updateCounts();
	}

	@Subscribe
	public void onInteractingChanged(InteractingChanged e)
	{
		Player me = client.getLocalPlayer();
		Actor src = e.getSource();
		if (me == null || src == null || src == me || e.getTarget() != me)
		{
			return;
		}
		Attackers.Attacker a = attackers.get(src);
		if (a == null)
		{
			attackers.put(src, attacker(src, client.getTickCount()));
		}
		else
		{
			a.lastTick = client.getTickCount();
		}
	}

	@Subscribe
	public void onNpcDespawned(NpcDespawned e)
	{
		attackers.remove(e.getNpc());
	}

	@Subscribe
	public void onPlayerDespawned(PlayerDespawned e)
	{
		attackers.remove(e.getPlayer());
	}

	@Subscribe
	public void onHitsplatApplied(HitsplatApplied e)
	{
		if (e.getActor() != client.getLocalPlayer())
		{
			return;
		}
		int type = e.getHitsplat().getHitsplatType();
		int amount = e.getHitsplat().getAmount();
		if (amount > 0 && damages(type))
		{
			hits.addLast(new int[]{client.getTickCount(), type, amount});
		}
	}

	@Subscribe
	public void onActorDeath(ActorDeath e)
	{
		if (e.getActor() == client.getLocalPlayer())
		{
			died();
		}
	}

	/**
	 * RuneLite saved a screenshot: if it is of your own death (told from the game event that made RuneLite take it,
	 * {@link ShotNamer}, never from its file), Death Log keeps a copy for that death's card.
	 */
	@Subscribe
	public void onScreenshotTaken(ScreenshotTaken e)
	{
		ShotNamer n = namer;
		if (n == null)
		{
			return;
		}
		long t = ownDeath(n.take(System.currentTimeMillis()));   // every screenshot takes its place in the queue
		if (!config.deathPictures() || t < 0 || e.getScreenshot() == null)
		{
			return;
		}
		BufferedImage img = e.getScreenshot();
		clientThread.invokeLater(() -> attachPicture(t, img));
	}

	/** When you died, if this screenshot is RuneLite's picture of your own death ("Death" / "Doom Death"); -1 = it isn't. */
	static long ownDeath(ShotNamer.Name n)
	{
		return ShotNamer.DEATHS.equals(n.type) && (ShotNamer.OWN_DEATH.equals(n.file) || ShotNamer.DOOM_DEATH.equals(n.file))
			? n.at : -1;
	}

	@Subscribe
	public void onChatMessage(ChatMessage e)
	{
		if (e.getType() != ChatMessageType.GAMEMESSAGE && e.getType() != ChatMessageType.SPAM)
		{
			return;
		}
		String raw = e.getMessage();
		String text = Text.removeTags(raw);
		if (text.startsWith("Oh dear, you are dead!"))
		{
			died();                                  // the back-up signal (counted once: SAME_DEATH_TICKS)
			return;
		}
		java.util.regex.Matcher w = Bosses.WAVE.matcher(text);
		if (w.find())
		{
			wave = Integer.parseInt(w.group(1));
			return;
		}
		Object[] kc = Bosses.killCount(raw);
		if (kc != null)
		{
			killCount((String) kc[0], (int) kc[1]);
		}
	}

	@Subscribe
	public void onConfigChanged(ConfigChanged e)
	{
		if (DeathLogConfig.GROUP.equals(e.getGroup()))
		{
			if ("look".equals(e.getKey()))
			{
				Theme theme = Theme.of(config.look());
				SwingUtilities.invokeLater(() -> panel.applyTheme(theme));
			}
			clientThread.invokeLater(this::refresh);
		}
	}

	// ---- a death ----

	/** Record a death of yours (client thread); twice for one death counts once. */
	private void died()
	{
		int tick = client.getTickCount();
		if (tick - lastDeathTick < SAME_DEATH_TICKS || client.getLocalPlayer() == null)
		{
			return;
		}
		lastDeathTick = tick;
		Death d = describe(tick);
		String key = profile;
		List<Death> all = new ArrayList<>(deaths);
		all.add(d);
		deaths = Collections.unmodifiableList(all);
		if (key != null)
		{
			executor.execute(() -> append(key, d));
		}
		updateCounts();
		if (config.chatMessage())
		{
			tell(d, all.size());
		}
		if (earlyPicture != null && Math.abs(d.at - earlyPictureAt) <= Pictures.SAME_MS)
		{
			savePicture(d.at, earlyPicture);
		}
		earlyPicture = null;
		refresh();
		wave = 0;
	}

	/** Everything the client shows about this death. */
	private Death describe(int tick)
	{
		Player me = client.getLocalPlayer();
		Death d = new Death();
		d.at = System.currentTimeMillis();
		d.world = client.getWorld();
		LocalPoint lp = me.getLocalLocation();
		WorldPoint wp = lp != null ? WorldPoint.fromLocalInstance(client, lp) : me.getWorldLocation();
		d.x = wp.getX();
		d.y = wp.getY();
		d.plane = wp.getPlane();
		d.region = wp.getRegionID();
		Areas.Place place = areas.of(d.x, d.y, d.plane);
		d.area = place.name;
		d.areaType = place.type;
		d.wildy = place.wildy;

		for (Map.Entry<Actor, Attackers.Attacker> a : attackers.entrySet())
		{
			a.getValue().onYou = a.getKey().getInteracting() == me;
		}
		List<Attackers.Attacker> on = Attackers.atDeath(attackers.values(), tick);
		if (on.isEmpty() && me.getInteracting() instanceof NPC)
		{
			on = List.of(attacker(me.getInteracting(), tick));   // nothing seen targeting you: what you were fighting
		}
		if (!on.isEmpty())
		{
			Attackers.Attacker k = on.get(0);
			d.killer = k.name;
			d.killerId = k.id;
			d.killerLevel = k.level;
			d.pvp = k.player;
			Map<String, Integer> others = new java.util.LinkedHashMap<>();
			for (Attackers.Attacker o : on.subList(1, on.size()))
			{
				others.merge(o.name, 1, Integer::sum);
			}
			for (Map.Entry<String, Integer> o : others.entrySet())
			{
				if (d.others.size() < 6)
				{
					d.others.add(o.getValue() > 1 ? o.getKey() + " ×" + o.getValue() : o.getKey());
				}
			}
		}

		int[] last = null;
		for (int[] h : hits)
		{
			d.damage += h[2];
			d.hits++;
			d.maxHit = Math.max(d.maxHit, h[2]);
			last = h;
		}
		d.lastHit = last == null ? 0 : last[2];
		d.cause = last == null ? null : cause(last[1]);
		d.prayer = client.getBoostedSkillLevel(Skill.PRAYER);
		d.combat = me.getCombatLevel();
		carried(d);
		if ("RAIDS".equals(d.areaType))
		{
			// the room from the raid's map (Chambers of Xeric), else the strongest monster near you (any raid)
			d.room = RaidRooms.COX.equals(d.area) ? RaidRooms.cox(d.x, d.y, d.plane, d.region) : null;
			if (d.room == null)
			{
				d.room = strongestNear(me);
			}
		}
		d.boss = bosses.bossOf(d.area, d.areaType, d.killer);
		d.killCount = d.boss == null ? -1 : DeathStats.killCountNow(killCounts, d.boss);
		d.wave = d.area != null && Bosses.WAVE_AREAS.containsKey(d.area) ? wave : 0;
		return d;
	}

	/** What the inventory and worn items were worth, and the most valuable of them. */
	private void carried(Death d)
	{
		List<long[]> items = new ArrayList<>();               // {id, value}
		for (int inv : new int[]{InventoryID.INV, InventoryID.WORN})
		{
			ItemContainer c = client.getItemContainer(inv);
			if (c == null)
			{
				continue;
			}
			for (Item it : c.getItems())
			{
				if (it.getId() <= 0 || it.getQuantity() <= 0)
				{
					continue;
				}
				int id = itemManager.canonicalize(it.getId());
				long each = id == ItemID.COINS ? 1 : id == ItemID.PLATINUM ? 1000 : itemManager.getItemPrice(id);
				long value = each * it.getQuantity();
				d.carried += value;
				if (value > 0)
				{
					items.add(new long[]{id, value});
				}
			}
		}
		items.sort((a, b) -> Long.compare(b[1], a[1]));
		for (long[] it : items.subList(0, Math.min(TOP_ITEMS, items.size())))
		{
			d.top.add(itemManager.getItemComposition((int) it[0]).getName() + "|" + it[1]);
		}
	}

	/** The strongest monster within {@link #NEAR_TILES} of you, by its room's name ({@link RaidRooms#boss}); null = none. */
	private String strongestNear(Player me)
	{
		WorldPoint at = me.getWorldLocation();
		NPC best = null;
		for (NPC n : client.getTopLevelWorldView().npcs())
		{
			if (n == null || n.getName() == null || n.getCombatLevel() <= 0 || n.getWorldLocation().distanceTo2D(at) > NEAR_TILES)
			{
				continue;
			}
			if (best == null || n.getCombatLevel() > best.getCombatLevel())
			{
				best = n;
			}
		}
		return best == null ? null : RaidRooms.boss(Text.removeTags(best.getName()));
	}

	private static Attackers.Attacker attacker(Actor a, int tick)
	{
		boolean player = a instanceof Player;
		String name = a.getName() == null ? null : Text.removeTags(a.getName());
		return new Attackers.Attacker(name, a instanceof NPC ? ((NPC) a).getId() : -1, a.getCombatLevel(), player, tick);
	}

	/** Hitsplats that take hitpoints (not heals, blocks, prayer or sanity drains). */
	static boolean damages(int type)
	{
		return type != HitsplatID.HEAL && type != HitsplatID.BLOCK_ME && type != HitsplatID.BLOCK_OTHER
			&& type != HitsplatID.PRAYER_DRAIN && type != HitsplatID.SANITY_DRAIN && type != HitsplatID.SANITY_RESTORE
			&& type != HitsplatID.CYAN_UP && type != HitsplatID.CYAN_DOWN && type != HitsplatID.DISEASE_BLOCKED;
	}

	static String cause(int type)
	{
		if (type == HitsplatID.POISON)
		{
			return "poison";
		}
		if (type == HitsplatID.VENOM)
		{
			return "venom";
		}
		if (type == HitsplatID.DISEASE)
		{
			return "disease";
		}
		if (type == HitsplatID.BURN)
		{
			return "burn";
		}
		if (type == HitsplatID.BLEED)
		{
			return "bleed";
		}
		return type == HitsplatID.DOOM ? "doom" : "hit";
	}

	/** The line in the chat box after a death. */
	private void tell(Death d, int number)
	{
		ChatMessageBuilder b = new ChatMessageBuilder()
			.append(ChatColorType.HIGHLIGHT).append("Death #" + number)
			.append(ChatColorType.NORMAL).append(": " + d.killedBy() + " at " + d.place() + ". ")
			.append(tripAName + ": " + counts[DeathLogConfig.Counter.TRIP_A.ordinal()]
				+ " · " + tripBName + ": " + counts[DeathLogConfig.Counter.TRIP_B.ordinal()]
				+ " · Today: " + counts[DeathLogConfig.Counter.TODAY.ordinal()]);
		if (d.boss != null)
		{
			int n = 0;
			for (Death x : deaths)
			{
				n += d.boss.equals(x.boss) ? 1 : 0;
			}
			b.append(" · " + d.boss + ": " + n);
		}
		chatMessageManager.queue(QueuedMessage.builder().type(ChatMessageType.CONSOLE).runeLiteFormattedMessage(b.build()).build());
	}

	private void killCount(String boss, int count)
	{
		bosses.learn(boss);
		Map<String, int[]> m = new HashMap<>(killCounts);
		int[] had = m.get(boss);
		m.put(boss, had == null ? new int[]{count, count} : new int[]{Math.min(had[0], count), Math.max(had[1], count)});
		killCounts = Collections.unmodifiableMap(m);
		if (profile != null)
		{
			configManager.setRSProfileConfiguration(DeathLogConfig.GROUP, KC, gson.toJson(m));
		}
		if (config.streakMessage() && Bosses.known(boss))
		{
			String shown = deathKey(boss);
			int[] run = DeathStats.runs(deaths, killCounts, shown);
			if (run[0] >= 0)
			{
				chatMessageManager.queue(QueuedMessage.builder().type(ChatMessageType.CONSOLE)
					.runeLiteFormattedMessage(streakLine(Bosses.display(shown), run, hasDied(shown))).build());
			}
		}
		SwingUtilities.invokeLater(panel::refresh);
	}

	/**
	 * "Vorkath: 48 kills since your last death (best 112)" / "...: 113 kills since your last death - new best!" (once,
	 * on the kill that passes the old best) / "Zulrah: 12 kills, no deaths yet".
	 */
	static String streakLine(String boss, int[] run, boolean died)
	{
		ChatMessageBuilder b = new ChatMessageBuilder().append(ChatColorType.HIGHLIGHT).append(boss + ": ")
			.append(ChatColorType.NORMAL).append(run[0] + (run[0] == 1 ? " kill" : " kills"));
		if (!died)
		{
			return b.append(", no deaths yet").build();
		}
		b.append(" since your last death");
		if (run[2] > 0 && run[0] == run[2] + 1)
		{
			return b.append(ChatColorType.HIGHLIGHT).append(" - new best!").build();
		}
		return b.append(" (best " + run[1] + ")").build();
	}

	/** The name deaths use for a kill count's boss ("Theatre of Blood Hard Mode" -> "Theatre of Blood"). */
	private static String deathKey(String kcName)
	{
		for (String b : new String[]{"Chambers of Xeric", "Theatre of Blood", "Tombs of Amascut", "Dagannoth Kings", "Barrows Chests"})
		{
			if (Bosses.countsFor(kcName, b))
			{
				return b;
			}
		}
		return kcName;
	}

	private boolean hasDied(String boss)
	{
		for (Death d : deaths)
		{
			if (boss.equals(d.boss))
			{
				return true;
			}
		}
		return false;
	}

	// ---- the account's data ----

	/** A different account (or the first tick of one): load its deaths, trips and kill counts (client thread). */
	private void checkProfile()
	{
		String key = configManager.getRSProfileKey();
		if (key == null || !loggedIn)
		{
			return;
		}
		if (!key.equals(profile))
		{
			profile = key;
			deaths = List.of();
			tripA = longSetting(TRIP_A, System.currentTimeMillis());
			tripB = longSetting(TRIP_B, System.currentTimeMillis());
			tripAName = stringSetting(TRIP_A + "Name", "Counter 1");
			tripBName = stringSetting(TRIP_B + "Name", "Counter 2");
			killCounts = readKillCounts();
			for (String b : killCounts.keySet())
			{
				bosses.learn(b);
			}
			executor.execute(() ->
			{
				List<Death> read = read(key);
				clientThread.invokeLater(() ->
				{
					if (key.equals(profile))
					{
						List<Death> all = new ArrayList<>(read);
						for (Death d : deaths)
						{
							all.add(d);              // a death while the file was read
						}
						deaths = Collections.unmodifiableList(all);
						refresh();
					}
				});
			});
			refresh();
		}
		if (loginResetsDue)
		{
			loginResetsDue = false;
			long now = System.currentTimeMillis();
			if (config.tripAReset() == DeathLogConfig.TripReset.LOGIN)
			{
				setTrip(true, now);
			}
			if (config.tripBReset() == DeathLogConfig.TripReset.LOGIN)
			{
				setTrip(false, now);
			}
			dailyResets();
		}
	}

	private void dailyResets()
	{
		if (profile == null)
		{
			return;
		}
		long midnight = DeathStats.startOfDay(System.currentTimeMillis(), ZoneId.systemDefault());
		if (config.tripAReset() == DeathLogConfig.TripReset.DAILY && tripA < midnight)
		{
			setTrip(true, midnight);
		}
		if (config.tripBReset() == DeathLogConfig.TripReset.DAILY && tripB < midnight)
		{
			setTrip(false, midnight);
		}
	}

	private void setTrip(boolean a, long since)
	{
		if (a)
		{
			tripA = since;
		}
		else
		{
			tripB = since;
		}
		configManager.setRSProfileConfiguration(DeathLogConfig.GROUP, a ? TRIP_A : TRIP_B, String.valueOf(since));
		refresh();
	}

	private long longSetting(String key, long otherwise)
	{
		String v = configManager.getRSProfileConfiguration(DeathLogConfig.GROUP, key);
		try
		{
			return v == null ? otherwise : Long.parseLong(v);
		}
		catch (NumberFormatException e)
		{
			return otherwise;
		}
	}

	private String stringSetting(String key, String otherwise)
	{
		String v = configManager.getRSProfileConfiguration(DeathLogConfig.GROUP, key);
		return v == null || v.isEmpty() ? otherwise : v;
	}

	private Map<String, int[]> readKillCounts()
	{
		String v = configManager.getRSProfileConfiguration(DeathLogConfig.GROUP, KC);
		if (v == null)
		{
			return Map.of();
		}
		try
		{
			Map<String, int[]> m = gson.fromJson(v, new TypeToken<Map<String, int[]>>()
			{
			}.getType());
			return m == null ? Map.of() : Collections.unmodifiableMap(m);
		}
		catch (JsonParseException e)
		{
			return Map.of();
		}
	}

	// ---- the deaths file (off the client thread) ----

	private Filepath file(String key) throws IOException
	{
		return getPluginDirectory().joinSegment(DEATHS_DIR).joinSegment(safe(key) + ".jsonl");
	}

	static String safe(String key)
	{
		return key.replaceAll("[^A-Za-z0-9._-]", "_");
	}

	private List<Death> read(String key)
	{
		List<Death> out = new ArrayList<>();
		try
		{
			Filepath f = file(key);
			if (!f.exists())
			{
				return out;
			}
			try (BufferedReader r = f.openBufferedReader())
			{
				for (String line = r.readLine(); line != null; line = r.readLine())
				{
					try
					{
						Death d = line.isBlank() ? null : gson.fromJson(line, Death.class);
						if (d != null)
						{
							out.add(d);
						}
					}
					catch (JsonParseException bad)
					{
						log.debug("Death Log: a bad line skipped", bad);
					}
				}
			}
		}
		catch (IOException e)
		{
			log.warn("Death Log: could not read the deaths", e);
		}
		return out;
	}

	private void append(String key, Death d)
	{
		try
		{
			Filepath f = file(key);
			f.getParent().createDirectories();
			f.write((gson.toJson(d) + "\n").getBytes(StandardCharsets.UTF_8), StandardOpenOption.CREATE,
				StandardOpenOption.APPEND);
		}
		catch (IOException e)
		{
			log.warn("Death Log: could not save a death", e);
		}
	}

	/** The whole file again (a note or a deletion). */
	private void rewrite(String key, List<Death> all)
	{
		try
		{
			Filepath f = file(key);
			f.getParent().createDirectories();
			StringBuilder sb = new StringBuilder();
			for (Death d : all)
			{
				sb.append(gson.toJson(d)).append('\n');
			}
			Filepath tmp = f.getParent().joinSegment(f.getFileName() + ".tmp");
			tmp.write(sb.toString().getBytes(StandardCharsets.UTF_8), StandardOpenOption.CREATE,
				StandardOpenOption.TRUNCATE_EXISTING, StandardOpenOption.WRITE);
			try
			{
				tmp.moveTo(f, StandardCopyOption.REPLACE_EXISTING, StandardCopyOption.ATOMIC_MOVE);
			}
			catch (AtomicMoveNotSupportedException e)
			{
				tmp.moveTo(f, StandardCopyOption.REPLACE_EXISTING);
			}
		}
		catch (IOException e)
		{
			log.warn("Death Log: could not save the deaths", e);
		}
	}

