	BufferedImage icon()
	{
		return skull;
	}

	/** Which panel sections are open (Bosses, What killed you, Where, Every death); closed until opened. */
	private final Map<String, Boolean> open = new java.util.concurrent.ConcurrentHashMap<>();

	boolean isOpen(String section)
	{
		return open.computeIfAbsent(section, k -> configManager != null
			&& "true".equals(configManager.getConfiguration(DeathLogConfig.GROUP, "open." + k)));
	}

	void setOpen(String section, boolean on)
	{
		open.put(section, on);
		if (configManager != null)
		{
			configManager.setConfiguration(DeathLogConfig.GROUP, "open." + section, String.valueOf(on));
		}
	}

	/** A counter's value now. */
	static int count(View v, DeathLogConfig.Counter c)
	{
		switch (c)
		{
			case LIFETIME:
				return v.deaths.size();
			case TODAY:
				return DeathStats.since(v.deaths, DeathStats.startOfDay(v.now, ZoneId.systemDefault()));
			case SESSION:
				return DeathStats.since(v.deaths, v.sessionStart);
			case LAST_HOUR:
				return DeathStats.since(v.deaths, v.now - DeathStats.HOUR_MS);
			case TRIP_A:
				return DeathStats.since(v.deaths, v.tripA);
			case TRIP_B:
				return DeathStats.since(v.deaths, v.tripB);
			default:
				return 0;
		}
	}

	private void updateCounts()
	{
		View v = view();
		for (DeathLogConfig.Counter c : DeathLogConfig.Counter.values())
		{
			counts[c.ordinal()] = count(v, c);
		}
	}

	/** The box on screen: the chosen counter. */
	String boxText()
	{
		return String.valueOf(counts[config.infoBox().ordinal()]);
	}

	String boxTooltip()
	{
		return "Death Log</br>" + tripAName + ": " + counts[DeathLogConfig.Counter.TRIP_A.ordinal()]
			+ "</br>" + tripBName + ": " + counts[DeathLogConfig.Counter.TRIP_B.ordinal()]
			+ "</br>Last hour: " + counts[DeathLogConfig.Counter.LAST_HOUR.ordinal()]
			+ "</br>This session: " + counts[DeathLogConfig.Counter.SESSION.ordinal()]
			+ "</br>Today: " + counts[DeathLogConfig.Counter.TODAY.ordinal()]
			+ "</br>All time: " + counts[DeathLogConfig.Counter.LIFETIME.ordinal()];
	}

	/** The box, the map skulls and the panel, after a change (client thread). */
	private void refresh()
	{
		updateCounts();
		boolean wantBox = config.infoBox() != DeathLogConfig.Counter.OFF && profile != null;
		if (wantBox && infoBox == null)
		{
			infoBox = new DeathInfoBox(skull, this);
			infoBoxManager.addInfoBox(infoBox);
		}
		else if (!wantBox && infoBox != null)
		{
			infoBoxManager.removeInfoBox(infoBox);
			infoBox = null;
		}
		worldMapPointManager.removeIf(DeathPoint.class::isInstance);
		if (config.mapMarkers())
		{
			List<Death> all = deaths;
			SimpleDateFormat when = new SimpleDateFormat("EEE d MMM HH:mm");
			for (int i = Math.max(0, all.size() - config.mapMarkerCount()); i < all.size(); i++)
			{
				Death d = all.get(i);
				if (d.from != null)
				{
					continue;                            // imported: no place known
				}
				DeathPoint p = new DeathPoint(new WorldPoint(d.x, d.y, d.plane), mapSkull);
				p.setName("Death #" + (i + 1));
				p.setTooltip("Death #" + (i + 1) + " · " + when.format(new Date(d.at)) + " · " + d.killedBy());
				worldMapPointManager.add(p);
			}
		}
		if (panel != null)
		{
			SwingUtilities.invokeLater(panel::refresh);
		}
	}

