	void renameTrip(boolean a, String name)
	{
		String n = name == null || name.isBlank() ? (a ? "Counter 1" : "Counter 2") : name.trim();
		clientThread.invokeLater(() ->
		{
			if (profile == null)
			{
				return;
			}
			if (a)
			{
				tripAName = n;
			}
			else
			{
				tripBName = n;
			}
			configManager.setRSProfileConfiguration(DeathLogConfig.GROUP, (a ? TRIP_A : TRIP_B) + "Name", n);
			refresh();
