	void setNote(Death d, String note)
	{
		clientThread.invokeLater(() ->
		{
			d.note = note == null || note.isBlank() ? null : note.trim();
			save();
		});
	}

	void delete(Death d)
	{
		clientThread.invokeLater(() ->
		{
			List<Death> all = new ArrayList<>(deaths);
			if (all.remove(d))
			{
				deaths = Collections.unmodifiableList(all);
				save();
				if (pictured.remove(d.at))
				{
					pictureGen++;
					executor.execute(() ->
					{
						try
						{
							pictureFile(d.at).deleteIfExists();
						}
						catch (IOException e)
						{
							log.warn("Death Log: could not delete a death's picture", e);
						}
					});
				}
			}
		});
	}

	/** Write the whole list (client thread → the executor). */
	private void save()
	{
		String key = profile;
		List<Death> all = deaths;
		if (key != null)
		{
			executor.execute(() -> rewrite(key, all));
		}
		refresh();
	}

	// ---- pictures: Death Log's copy of RuneLite's death screenshot, shown on the death's card ----

	/** A screenshot of your death taken at {@code t}: its death's picture, or kept until that death is recorded (client thread). */
	private void attachPicture(long t, BufferedImage img)
	{
		Death d = nearestDeath(deaths, t, Set.of());
		if (d != null)
		{
			savePicture(d.at, img);
		}
		else
		{
			earlyPicture = img;                  // the screenshot came first: died() attaches it
			earlyPictureAt = t;
		}
	}

	/** The death within {@link Pictures#SAME_MS} of {@code t} that has no picture yet, the nearest; null = none. */
	private Death nearestDeath(List<Death> all, long t, Set<Long> taken)
	{
		Death best = null;
		for (Death d : all)
		{
			long gap = Math.abs(d.at - t);
			if (gap <= Pictures.SAME_MS && !pictured.contains(d.at) && !taken.contains(d.at)
				&& (best == null || gap < Math.abs(best.at - t)))
			{
				best = d;
			}
		}
		return best;
	}

	/** Keep a copy of a death's screenshot (any thread; written on the executor). */
	private void savePicture(long at, BufferedImage img)
	{
		executor.execute(() -> writePicture(at, img));
	}

	/** On the executor: write the copy, then show it. False = it couldn't be written. */
	private boolean writePicture(long at, BufferedImage img)
	{
		try
		{
			Filepath dir = getPluginDirectory().joinSegment(Pictures.DIR);
			dir.createDirectories();
			Pictures.write(img, dir.joinSegment(Pictures.fileName(at)));
			pictured.add(at);
			pictureGen++;
		}
		catch (IOException | RuntimeException e)
		{
			log.warn("Death Log: could not keep a death's picture", e);
			return false;
		}
		if (panel != null)
		{
			SwingUtilities.invokeLater(panel::refresh);
		}
		return true;
	}

	private Filepath pictureFile(long at) throws IOException
	{
		return getPluginDirectory().joinSegment(Pictures.DIR).joinSegment(Pictures.fileName(at));
	}

	/** Which deaths have a picture (the executor, at start). */
	private void readPictures()
	{
		try
		{
			Filepath dir = getPluginDirectory().joinSegment(Pictures.DIR);
			if (!dir.exists())
			{
				return;
			}
			try (java.util.stream.Stream<Filepath> files = dir.walk(1))
			{
				for (Filepath f : (Iterable<Filepath>) files::iterator)
				{
					long at = Pictures.timeOf(f.getFileName());
					if (at > 0)
					{
						pictured.add(at);
					}
				}
				pictureGen++;
			}
		}
		catch (IOException e)
		{
			log.warn("Death Log: could not read the pictures folder", e);
		}
		if (panel != null)
		{
			SwingUtilities.invokeLater(panel::refresh);
		}
	}

	boolean hasPicture(Death d)
	{
		return pictured.contains(d.at);
	}

	/** Changes whenever a death's picture is added or removed. */
	int pictureGen()
	{
		return pictureGen;
	}

	/** A death's picture, no wider than {@code maxWidth} (0 = as kept), handed to {@code then} on Swing's thread (null = unreadable). */
	void picture(Death d, int maxWidth, Consumer<BufferedImage> then)
	{
		long at = d.at;
		executor.execute(() ->
		{
			BufferedImage img = null;
			try
			{
				img = Pictures.read(pictureFile(at));
				if (img != null && maxWidth > 0)
				{
					img = Pictures.scaled(img, maxWidth);
				}
			}
			catch (IOException | RuntimeException e)
			{
				log.debug("Death Log: could not read a death's picture", e);
			}
			BufferedImage out = img;
			SwingUtilities.invokeLater(() -> then.accept(out));
		});
	}

	/** The logged-in player's name, for the screenshot import (set on the client thread). */
	private volatile String playerName;

	/**
	 * Deaths from before Death Log, from RuneLite's death screenshots: you choose the screenshots folder (or your name's
	 * folder in it, or its Deaths folder). With several players' folders, only the logged-in player's are read.
	 */
	void importScreenshots(Component parent)
	{
		if (profile == null)
		{
			JOptionPane.showMessageDialog(parent, "Log in first: the deaths go to the account logged in.");
			return;
		}
		// hidden folders shown: .runelite starts with a dot, and it's the one to pick (2026-11-08: the user couldn't find it)
		Filepath.Chooser chooser = new Filepath.Chooser().setIsOpen().setAcceptsDirectories().setFileHidingEnabled(false)
			.setDialogTitle("Death Log: pick your .runelite folder, then click Open");
		if (!System.getProperty("os.name", "").toLowerCase(java.util.Locale.ROOT).startsWith("windows"))
		{
			// it opens in the home folder (Linux, Mac), where .runelite is: picked already, so Open is the only click
			// (checked 11-08 with RuneLite's own chooser: clicking its Open button returns .runelite). Windows opens in
			// Documents, one folder below .runelite, so nothing is picked there.
			chooser.setFileName(".runelite");
		}
		List<Filepath> picked = chooser.showDialog(parent);
		if (picked == null || picked.isEmpty())
		{
			return;
		}
		Filepath root = picked.get(0);
		String me = playerName;
		executor.execute(() ->
		{
			List<Long> times = new ArrayList<>();
			Map<Long, Filepath> shots = new HashMap<>();   // each death screenshot of yours, by its time
			int skipped = 0;
			boolean failed = false;
			try
			{
				skipped = DeathImport.find(root, me, ZoneId.systemDefault(), shots);
				times.addAll(shots.keySet());
			}
			catch (IOException | RuntimeException e)
			{
				log.warn("Death Log: could not read the screenshots", e);
				failed = true;
			}
			boolean couldNotRead = failed;
			int others = skipped;
			clientThread.invokeLater(() ->
			{
				List<Death> add = DeathImport.fresh(times, deaths);
				if (!add.isEmpty())
				{
					List<Death> all = new ArrayList<>(deaths);
					all.addAll(add);
					all.sort(java.util.Comparator.comparingLong(d -> d.at));
					deaths = Collections.unmodifiableList(all);
					save();
				}
				// each screenshot becomes the picture of its death (recorded or just imported), when it has none yet
				Map<Long, Filepath> attach = new HashMap<>();   // death time -> its screenshot
				if (config.deathPictures())
				{
					for (Map.Entry<Long, Filepath> f : shots.entrySet())
					{
						Death d = nearestDeath(deaths, f.getKey(), attach.keySet());
						if (d != null)
						{
							attach.put(d.at, f.getValue());
						}
					}
				}
				String said = couldNotRead && times.isEmpty()
					? "Death Log couldn't read that folder (is it there?). Try again and pick your .runelite folder."
					: times.isEmpty()
					? "No death screenshots of yours were found there." + (others > 0 ? " (" + others + " in other players' folders: choose your own folder.)" : "")
						+ "\n\nRuneLite saves them only with its Screenshot plugin's \"Screenshot deaths\" setting on, in .runelite/screenshots/<your name>/Deaths."
					: add.isEmpty()
						? (times.size() == 1 ? "That death is" : "All " + times.size() + " of those deaths are") + " already in the log."
					: "Imported " + add.size() + " of " + times.size() + " death screenshots"
						+ (times.size() > add.size() ? " (the rest were already in the log)" : "") + "."
						+ "\nAn imported death has the date and time only - not what killed you or where.";
				executor.execute(() ->
				{
					int pictures = 0;
					for (Map.Entry<Long, Filepath> a : attach.entrySet())
					{
						try
						{
							BufferedImage img = Pictures.read(a.getValue());
							pictures += img != null && writePicture(a.getKey(), img) ? 1 : 0;
						}
						catch (IOException e)
						{
							log.warn("Death Log: could not read a death screenshot", e);
						}
					}
					String say = said + (pictures == 0 ? "" : "\n\nAdded " + (pictures == 1 ? "a picture" : pictures + " pictures")
						+ " to " + (pictures == 1 ? "its death" : "their deaths") + ": click one on a death's card to see it big.");
					SwingUtilities.invokeLater(() -> JOptionPane.showMessageDialog(parent, say, "Import old deaths", JOptionPane.INFORMATION_MESSAGE));
				});
			});
		});
	}

	/** Every death as a spreadsheet (CSV), to a file you choose. */
	void exportCsv(Component parent)
	{
		List<Death> all = deaths;
		List<Filepath> picked = new Filepath.Chooser().setIsSave().setAcceptsFiles()
			.setDialogTitle("Export your deaths").addExtensionFilter("Spreadsheet (CSV)", "csv")
			.setDefaultExtension("csv").setFileName("deaths.csv").showDialog(parent);
		if (picked == null || picked.isEmpty())
		{
			return;
		}
		Filepath out = picked.get(0);
		executor.execute(() ->
		{
			try
			{
				out.write(DeathCsv.of(all).getBytes(StandardCharsets.UTF_8), StandardOpenOption.CREATE,
					StandardOpenOption.TRUNCATE_EXISTING, StandardOpenOption.WRITE);
			}
			catch (IOException e)
			{
				log.warn("Death Log: export failed", e);
			}
		});
	}
}

