package com.deathlog;

import java.time.Instant;
import java.time.LocalDate;
import java.time.ZoneId;
import java.util.ArrayList;
import java.util.Comparator;
import java.util.HashMap;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.function.Function;

/** Counting over the saved deaths — pure, no game state, so it is tested on its own. */
final class DeathStats
{
	static final long HOUR_MS = 3_600_000L;

	private DeathStats()
	{
	}

	/** Deaths at or after {@code from} (epoch ms). */
	static int since(List<Death> deaths, long from)
	{
		int n = 0;
		for (Death d : deaths)
		{
			if (d.at >= from)
			{
				n++;
			}
		}
		return n;
	}

	/** Local midnight of the day {@code now} is in. */
	static long startOfDay(long now, ZoneId zone)
	{
		return LocalDate.ofInstant(Instant.ofEpochMilli(now), zone).atStartOfDay(zone).toInstant().toEpochMilli();
	}

	/** Deaths per day for the last {@code days} days, oldest first; the last is today. */
	static int[] perDay(List<Death> deaths, long now, int days, ZoneId zone)
	{
		int[] out = new int[days];
		LocalDate today = LocalDate.ofInstant(Instant.ofEpochMilli(now), zone);
		for (Death d : deaths)
		{
			long ago = today.toEpochDay() - LocalDate.ofInstant(Instant.ofEpochMilli(d.at), zone).toEpochDay();
			if (ago >= 0 && ago < days)
			{
				out[days - 1 - (int) ago]++;
			}
		}
		return out;
	}

	/** The most common values, most first (ties: the latest first): name -> count. Nulls are skipped. */
	static List<Map.Entry<String, Integer>> top(List<Death> deaths, Function<Death, String> what, int n)
	{
		Map<String, Integer> count = new HashMap<>();
		Map<String, Long> last = new HashMap<>();
		for (Death d : deaths)
		{
			String k = what.apply(d);
			if (k != null)
			{
				count.merge(k, 1, Integer::sum);
				last.merge(k, d.at, Math::max);
			}
		}
		List<Map.Entry<String, Integer>> out = new ArrayList<>(count.entrySet());
		out.sort(Comparator.<Map.Entry<String, Integer>>comparingInt(Map.Entry::getValue).reversed()
			.thenComparing(e -> -last.get(e.getKey())));
		return out.subList(0, Math.min(n, out.size()));
	}

	/** Longest time between two deaths in a row (and from the last one to {@code now}), ms; 0 with no deaths. */
	static long longestAlive(List<Death> deaths, long now)
	{
		long best = 0;
		long prev = -1;
		List<Death> sorted = new ArrayList<>(deaths);
		sorted.sort(Comparator.comparingLong(d -> d.at));
		for (Death d : sorted)
		{
			if (prev >= 0)
			{
				best = Math.max(best, d.at - prev);
			}
			prev = d.at;
		}
		return prev < 0 ? 0 : Math.max(best, now - prev);
	}

	/** One boss: its deaths, the kills since this plugin first saw its kill count, and the death rate. */
	static final class BossRow
	{
		final String boss;
		final int deaths;
		/** Kills since the first kill-count message seen; -1 = no kill count seen yet. */
		final int kills;
		/** The kill count now (the game's, all time); -1 = not seen. */
		final int killCount;
		/** The highest wave reached in a death (wave fights); 0 = none. */
		final int bestWave;
		final long lastAt;
		/** Kills since your last death to it, and the most in a row between deaths; -1 = not known. */
		int sinceDeath = -1;
		int bestRun = -1;

		BossRow(String boss, int deaths, int kills, int killCount, int bestWave, long lastAt)
		{
			this.boss = boss;
			this.deaths = deaths;
			this.kills = kills;
			this.killCount = killCount;
			this.bestWave = bestWave;
			this.lastAt = lastAt;
		}

		/** Deaths per attempt (deaths / (deaths + kills)), 0-1; -1 = no kills known. */
		double deathRate()
		{
			return kills < 0 ? -1 : (double) deaths / Math.max(1, deaths + kills);
		}
	}

	/**
	 * Every boss with a death or a kill count: deaths, kills since the plugin first saw a kill count ({@code kc}: kill-
	 * count name -> {first count seen, latest count}), most deaths first.
	 */
	static List<BossRow> bosses(List<Death> deaths, Map<String, int[]> kc)
	{
		Map<String, int[]> dead = new LinkedHashMap<>();      // boss -> {deaths, best wave}
		Map<String, Long> last = new HashMap<>();
		for (Death d : deaths)
		{
			if (d.boss == null)
			{
				continue;
			}
			int[] r = dead.computeIfAbsent(d.boss, k -> new int[2]);
			r[0]++;
			r[1] = Math.max(r[1], d.wave);
			last.merge(d.boss, d.at, Math::max);
		}
		List<BossRow> out = new ArrayList<>();
		for (Map.Entry<String, int[]> e : dead.entrySet())
		{
			int kills = -1;
			int now = -1;
			for (Map.Entry<String, int[]> k : kc.entrySet())
			{
				if (Bosses.countsFor(k.getKey(), e.getKey()))
				{
					kills = Math.max(0, kills) + k.getValue()[1] - k.getValue()[0] + 1;
					now = Math.max(0, now) + k.getValue()[1];
				}
			}
			BossRow row = new BossRow(e.getKey(), e.getValue()[0], kills, now, e.getValue()[1], last.get(e.getKey()));
			int[] run = runs(deaths, kc, e.getKey());
			row.sinceDeath = run[0];
			row.bestRun = run[1];
			out.add(row);
		}
		// bosses killed but never died to: shown too (0 deaths is worth seeing)
		for (Map.Entry<String, int[]> k : kc.entrySet())
		{
			boolean listed = false;
			for (String b : dead.keySet())
			{
				listed |= Bosses.countsFor(k.getKey(), b);
			}
			if (!listed && Bosses.known(k.getKey()))
			{
				BossRow row = new BossRow(k.getKey(), 0, k.getValue()[1] - k.getValue()[0] + 1, k.getValue()[1], 0, 0);
				row.sinceDeath = row.kills;
				row.bestRun = row.kills;
				out.add(row);
			}
		}
		out.sort(Comparator.<BossRow>comparingInt(r -> r.deaths).reversed()
			.thenComparing(Comparator.<BossRow>comparingInt(r -> r.kills).reversed()));
		return out;
	}

	/** A boss's kill count now (its kill-count names added up, the raids' and Dagannoth Kings' parts too); -1 = none. */
	static int killCountNow(Map<String, int[]> kc, String boss)
	{
		int n = -1;
		for (Map.Entry<String, int[]> k : kc.entrySet())
		{
			if (Bosses.countsFor(k.getKey(), boss))
			{
				n = Math.max(0, n) + k.getValue()[1];
			}
		}
		return n;
	}

	/** The kill count Death Log first saw for a boss (added up like {@link #killCountNow}); -1 = none. */
	private static int killCountFirst(Map<String, int[]> kc, String boss)
	{
		int n = -1;
		for (Map.Entry<String, int[]> k : kc.entrySet())
		{
			if (Bosses.countsFor(k.getKey(), boss))
			{
				n = Math.max(0, n) + k.getValue()[0];
			}
		}
		return n;
	}

	/**
	 * ⭐ KILLS SINCE YOUR LAST DEATH (user, 2026-11-04: "i like one a lot"), like a "days without an accident" sign:
	 * {kills since the last death to this boss, the most kills in a row (the current run included), the most in a row
	 * BEFORE the current run}; -1 = not known. Each death keeps the boss's kill count at that moment (Death.killCount);
	 * a death before any kill count was seen counts from the first one seen after it.
	 */
	static int[] runs(List<Death> deaths, Map<String, int[]> kc, String boss)
	{
		int now = killCountNow(kc, boss);
		if (now < 0)
		{
			return new int[]{-1, -1, -1};
		}
		int first = killCountFirst(kc, boss);
		int past = -1;
		int prev = first - 1;                  // runs count from the first kill count seen, that kill included
		for (Death d : deaths)
		{
			if (!boss.equals(d.boss))
			{
				continue;
			}
			if (d.killCount >= 0 && d.killCount >= prev)
			{
				past = Math.max(past, d.killCount - prev);
			}
			prev = d.killCount >= 0 ? d.killCount : first - 1;
		}
		int since = Math.max(0, now - prev);
		return new int[]{since, Math.max(past, since), past};
	}

	/** How the "Over time" graph groups deaths. */
	enum Step
	{
		DAY("Days", 30), WEEK("Weeks", 26), MONTH("Months", 12);

		final String label;
		final int count;

		Step(String label, int count)
		{
			this.label = label;
			this.count = count;
		}
	}

	/** Deaths per day / week (from Monday) / month, the last {@code step.count} of them, oldest first: {labels, counts}. */
	static Object[] overTime(List<Death> deaths, long now, Step step, ZoneId zone)
	{
		LocalDate today = LocalDate.ofInstant(Instant.ofEpochMilli(now), zone);
		LocalDate[] starts = new LocalDate[step.count];
		for (int i = 0; i < step.count; i++)
		{
			int back = step.count - 1 - i;
			starts[i] = step == Step.DAY ? today.minusDays(back)
				: step == Step.WEEK ? today.minusDays(today.getDayOfWeek().getValue() - 1L).minusWeeks(back)
				: today.withDayOfMonth(1).minusMonths(back);
		}
		int[] counts = new int[step.count];
		for (Death d : deaths)
		{
			LocalDate day = LocalDate.ofInstant(Instant.ofEpochMilli(d.at), zone);
			for (int i = step.count - 1; i >= 0; i--)
			{
				if (!day.isBefore(starts[i]))
				{
					if (i < step.count - 1 || !day.isAfter(today))
					{
						counts[i]++;
					}
					break;
				}
			}
		}
		String[] labels = new String[step.count];
		for (int i = 0; i < step.count; i++)
		{
			LocalDate a = starts[i];
			labels[i] = step == Step.MONTH ? a.getMonth().getDisplayName(java.time.format.TextStyle.SHORT, java.util.Locale.ENGLISH)
				: a.getDayOfMonth() + " " + a.getMonth().getDisplayName(java.time.format.TextStyle.SHORT, java.util.Locale.ENGLISH);
		}
		return new Object[]{labels, counts};
	}

	/** Deaths by the hour of the day they happened in (0-23). */
	static int[] byHour(List<Death> deaths, ZoneId zone)
	{
		int[] out = new int[24];
		for (Death d : deaths)
		{
			out[Instant.ofEpochMilli(d.at).atZone(zone).getHour()]++;
		}
		return out;
	}

	/** Deaths by the day of the week, Monday first. */
	static int[] byWeekday(List<Death> deaths, ZoneId zone)
	{
		int[] out = new int[7];
		for (Death d : deaths)
		{
			out[Instant.ofEpochMilli(d.at).atZone(zone).getDayOfWeek().getValue() - 1]++;
		}
		return out;
	}

	/**
	 * The kills between deaths to one boss, oldest first, and the current run last: {run, -1 when not known}. The bars of
	 * the Bosses graph — longer bars as you get better.
	 */
	static List<int[]> runSeries(List<Death> deaths, Map<String, int[]> kc, String boss)
	{
		List<int[]> out = new ArrayList<>();
		int now = killCountNow(kc, boss);
		int first = 0;
		for (Map.Entry<String, int[]> k : kc.entrySet())
		{
			first += Bosses.countsFor(k.getKey(), boss) ? k.getValue()[0] : 0;
		}
		int prev = first - 1;
		for (Death d : deaths)
		{
			if (!boss.equals(d.boss))
			{
				continue;
			}
			out.add(new int[]{now >= 0 && d.killCount >= 0 && d.killCount >= prev ? d.killCount - prev : -1});
			prev = d.killCount >= 0 ? d.killCount : first - 1;
		}
		out.add(new int[]{now >= 0 ? Math.max(0, now - prev) : -1});
		return out;
	}

	/** The wave of each death at a wave fight ({@code area}), oldest first; deaths with no wave known are left out. */
	static List<Death> waveDeaths(List<Death> deaths, String area)
	{
		List<Death> out = new ArrayList<>();
		for (Death d : deaths)
		{
			if (area.equals(d.area) && d.wave > 0)
			{
				out.add(d);
			}
		}
		return out;
	}

	/** The wave fights you have died in (with a wave known). */
	static List<String> waveAreas(List<Death> deaths)
	{
		List<String> out = new ArrayList<>();
		for (Death d : deaths)
		{
			if (d.wave > 0 && d.area != null && !out.contains(d.area))
			{
				out.add(d.area);
			}
		}
		return out;
	}

	/** The hardest killing blows, hardest first. */
	static List<Death> hardestHits(List<Death> deaths, int n)
	{
		List<Death> out = new ArrayList<>();
		for (Death d : deaths)
		{
			if (d.lastHit > 0)
			{
				out.add(d);
			}
		}
		out.sort(Comparator.comparingInt((Death d) -> d.lastHit).reversed());
		return out.subList(0, Math.min(n, out.size()));
	}

	/** "2h 05m" / "3d 4h" / "45s". */
	static String duration(long ms)
	{
		long s = Math.max(0, ms / 1000);
		if (s < 60)
		{
			return s + "s";
		}
		long m = s / 60;
		if (m < 60)
		{
			return m + "m";
		}
		long h = m / 60;
		if (h < 48)
		{
			return h + "h " + String.format("%02dm", m % 60);
		}
		return h / 24 + "d " + h % 24 + "h";
	}

	/** Deaths an hour over {@code ms}; 0 under a minute. */
	static double perHour(int deaths, long ms)
	{
		return ms < 60_000 ? 0 : deaths * (double) HOUR_MS / ms;
	}
}

