import java.awt.FontMetrics;
import java.awt.GradientPaint;
import java.awt.Graphics2D;
import java.awt.RenderingHints;
import java.awt.geom.Path2D;
import java.awt.geom.RoundRectangle2D;
import net.runelite.client.ui.FontManager;

/** Drawing in the panel's theme: cards, text (shadowed or glowing), tags, bars, the skull, the tombstone. */
final class Draw
{
	private Draw()
	{
	}

	static Font bold()
	{
		return FontManager.getRunescapeBoldFont();
	}

	static Font small()
	{
		return FontManager.getRunescapeSmallFont();
	}

	static Font plain()
	{
		return FontManager.getRunescapeFont();
	}

	static void smooth(Graphics2D g)
	{
		g.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
		g.setRenderingHint(RenderingHints.KEY_TEXT_ANTIALIASING, RenderingHints.VALUE_TEXT_ANTIALIAS_OFF);
	}

	/** A card in the theme's shape. */
	static void card(Graphics2D g, Theme t, int x, int y, int w, int h)
	{
		switch (t.card)
		{
			case BEVEL:
				bevel(g, t, x, y, w, h);
				return;
			case STONE:
				g.setPaint(new GradientPaint(x, y, t.cardFill.brighter(), x, y + h, t.cardFill));
				g.fill(new RoundRectangle2D.Double(x, y, w - 1, h - 1, t.radius, t.radius));
				break;
			case FLAT:
				g.setColor(t.cardFill);
				g.fillRect(x, y, w, h);
				break;
			default:
				g.setColor(t.cardFill);
				g.fill(new RoundRectangle2D.Double(x, y, w - 1, h - 1, t.radius, t.radius));
				break;
		}
		if (t.lava)
		{
			// embers under the stone: a glow along the lower edge
			g.setPaint(new GradientPaint(x, y + h - 7, new Color(0xFF, 0x50, 0x00, 0), x, y + h, new Color(0xFF, 0x60, 0x10, 90)));
			g.fill(new RoundRectangle2D.Double(x + 1, y + h - 8, w - 3, 7, t.radius, t.radius));
		}
		if (t.cardEdge != null)
		{
			g.setColor(t.cardEdge);
			g.draw(new RoundRectangle2D.Double(x + 0.5, y + 0.5, w - 2, h - 2, t.radius, t.radius));
		}
	}

	/**
	 * Molten rock in a box: basalt, glowing cracks, and a lava pool with a wavy surface along the bottom (Infernal).
	 * Fixed shapes (no randomness per frame), clipped to {@code shape}.
	 */
	static void lava(Graphics2D g, java.awt.Shape shape, int w, int h)
	{
		java.awt.Shape clip = g.getClip();
		g.clip(shape);
		g.setPaint(new GradientPaint(0, 0, new Color(0x2A, 0x14, 0x0C), w, h, new Color(0x14, 0x09, 0x06)));
		g.fillRect(0, 0, w, h);
		// the pool: a wavy surface, deep orange to bright yellow at the bottom
		int top = h - 30;
		Path2D pool = new Path2D.Double();
		pool.moveTo(0, h);
		pool.lineTo(0, top + 6);
		for (int x = 0; x <= w; x += 4)
		{
			pool.lineTo(x, top + 4 * Math.sin(x / 13.0) + 2 * Math.sin(x / 5.0 + 1));
		}
		pool.lineTo(w, h);
		pool.closePath();
		g.setPaint(new GradientPaint(0, top - 6, new Color(0xC8, 0x2A, 0x00), 0, h, new Color(0xFF, 0xB0, 0x20)));
		g.fill(pool);
		// heat haze over the surface
		g.setPaint(new GradientPaint(0, top - 22, new Color(0xFF, 0x60, 0x00, 0), 0, top + 4, new Color(0xFF, 0x60, 0x00, 70)));
		g.fillRect(0, top - 22, w, 26);
		// crusted rock floating on the pool
		g.setColor(new Color(0x2A, 0x12, 0x0A, 210));
		g.fillOval(w / 5, top + 6, 22, 7);
		g.fillOval(w / 2 + 10, top + 12, 30, 8);
		g.fillOval(w - 40, top + 4, 18, 6);
		// cracks: a wide soft glow, then a bright core
		// only in the empty top-right corner, above the 14-day line (it starts 36 down)
		int[][] cracks = {{w - 74, 0, w - 66, 10, w - 71, 20, w - 62, 28}, {w - 34, 2, w - 39, 13, w - 31, 24},
			{w - 108, 0, w - 102, 9}};
		for (int[] c : cracks)
		{
			Path2D p = new Path2D.Double();
			p.moveTo(c[0], c[1]);
			for (int i = 2; i + 1 < c.length; i += 2)
			{
				p.lineTo(c[i], c[i + 1]);
			}
			g.setStroke(new BasicStroke(5f, BasicStroke.CAP_ROUND, BasicStroke.JOIN_ROUND));
			g.setColor(new Color(0xFF, 0x50, 0x00, 40));
			g.draw(p);
			g.setStroke(new BasicStroke(1.3f, BasicStroke.CAP_ROUND, BasicStroke.JOIN_ROUND));
			g.setColor(new Color(0xE0, 0x6A, 0x20, 200));
			g.draw(p);
		}
		g.setStroke(new BasicStroke(1f));
		g.setClip(clip);
	}

	/** The game's bevelled box: light top-left, dark bottom-right. */
	static void bevel(Graphics2D g, Theme t, int x, int y, int w, int h)
	{
		g.setColor(t.cardFill);
		g.fillRect(x, y, w, h);
		g.setColor(t.bevelDark);
		g.drawRect(x, y, w - 1, h - 1);
		g.setColor(t.bevelLight);
		g.drawLine(x + 1, y + 1, x + w - 2, y + 1);
		g.drawLine(x + 1, y + 1, x + 1, y + h - 2);
		g.setColor(new Color(0x10, 0x0D, 0x09));
		g.drawLine(x + 1, y + h - 2, x + w - 2, y + h - 2);
		g.drawLine(x + w - 2, y + 1, x + w - 2, y + h - 2);
	}

	/** Text in the theme: with the game's black shadow when the theme has it. */
	static void text(Graphics2D g, Theme t, String s, int x, int y, Color c)
	{
		if (t.shadow)
		{
			g.setColor(Color.BLACK);
			g.drawString(s, x + 1, y + 1);
		}
		g.setColor(c);
		g.drawString(s, x, y);
	}

	/** A big number: shadowed or glowing as the theme wants. */
	static void number(Graphics2D g, Theme t, String s, int x, int y, Color c)
	{
		if (t.glow != null)
		{
			Composite was = g.getComposite();
			g.setColor(t.glow);
			boolean big = g.getFont().getSize2D() >= 20;      // small numbers: a faint halo only, so they stay sharp
			for (int r = big ? 3 : 1; r >= 1; r--)
			{
				g.setComposite(AlphaComposite.getInstance(AlphaComposite.SRC_OVER, big ? 0.10f : 0.06f));
				for (int dx = -r; dx <= r; dx++)
				{
					for (int dy = -r; dy <= r; dy++)
					{
						if (dx * dx + dy * dy <= r * r)
						{
							g.drawString(s, x + dx, y + dy);
						}
					}
				}
			}
			g.setComposite(was);
		}
		text(g, t, s, x, y, c);
	}

	static void right(Graphics2D g, Theme t, String s, int rightX, int y, Color c)
	{
		text(g, t, s, rightX - g.getFontMetrics().stringWidth(s), y, c);
	}

	static void centre(Graphics2D g, Theme t, String s, int cx, int y, Color c)
	{
		text(g, t, s, cx - g.getFontMetrics().stringWidth(s) / 2, y, c);
	}

	/** {@code s} cut with "..." to fit {@code width}. */
	static String fit(FontMetrics fm, String s, int width)
	{
		if (s == null || fm.stringWidth(s) <= width)
		{
			return s;
		}
		String dots = "...";
		int n = s.length();
		while (n > 0 && fm.stringWidth(s.substring(0, n) + dots) > width)
		{
			n--;
		}
		return s.substring(0, n).trim() + dots;
	}

	/** A small rounded tag; returns its width. */
	static int chip(Graphics2D g, Theme t, int x, int y, String s, Color fg)
	{
		g.setFont(small());
		int w = g.getFontMetrics().stringWidth(s) + 12;
		g.setColor(t.chip);
		if (t.card == Theme.Card.BEVEL || t.card == Theme.Card.FLAT)
		{
			g.fillRect(x, y, w, 15);
		}
		else
		{
			g.fill(new RoundRectangle2D.Double(x, y, w, 15, 15, 15));
		}
		text(g, t, s, x + 6, y + 11, fg);
		return w;
	}

	/** A progress bar: {@code frac} of it filled. */
	static void bar(Graphics2D g, Theme t, int x, int y, int w, int h, double frac, Color fill)
	{
		double f = Math.max(0, Math.min(1, frac));
		if (t.card == Theme.Card.BEVEL)
		{
			// the game's health bar: green on red
			g.setColor(new Color(0xA0, 0x00, 0x00));
			g.fillRect(x, y, w, h);
			g.setColor(fill.darker());
			g.fillRect(x, y, (int) (w * f), h);
			g.setColor(t.bevelDark);
			g.drawRect(x, y, w, h);
			return;
		}
		g.setColor(t.chip);
		g.fill(new RoundRectangle2D.Double(x, y, w, h, h, h));
		if (f > 0)
		{
			g.setColor(fill);
			g.fill(new RoundRectangle2D.Double(x, y, Math.max(h, w * f), h, h, h));
		}
	}

	/** A little skull. */
	static void skull(Graphics2D g, int x, int y, int s, Color c)
	{
		g.setColor(c);
		g.fillOval(x, y, s, (int) (s * 0.85));
		g.fillRoundRect(x + s / 4, y + s / 2, s / 2, s / 2, 3, 3);
		g.setColor(new Color(0x20, 0x18, 0x18));
		g.fillOval(x + s / 5, y + s / 3, Math.max(2, s / 4), Math.max(2, s / 4));
		g.fillOval(x + s - s / 5 - s / 4, y + s / 3, Math.max(2, s / 4), Math.max(2, s / 4));
	}

	/** The tombstone outline (rounded top) in a box. */
	static Path2D tombstone(int x, int y, int w, int h)
	{
		Path2D p = new Path2D.Double();
		p.moveTo(x, y + h);
		p.lineTo(x, y + w / 2.0);
		p.quadTo(x, y, x + w / 2.0, y);
		p.quadTo(x + w, y, x + w, y + w / 2.0);
		p.lineTo(x + w, y + h);
		p.closePath();
		return p;
	}

	/** Carved text: a light edge under dark letters. */
	static void carved(Graphics2D g, String s, int cx, int y, Color deep, Color lit)
	{
		int x = cx - g.getFontMetrics().stringWidth(s) / 2;
		g.setColor(lit);
		g.drawString(s, x + 1, y + 1);
		g.setColor(deep);
		g.drawString(s, x, y);
	}

	/** Dots of light (embers, motes) at fixed places so it does not flicker. */
	static void motes(Graphics2D g, Color c, int x, int y, int w, int h)
	{
		Composite was = g.getComposite();
		long seed = 7;
		for (int i = 0; i < 18; i++)
		{
			seed = seed * 6364136223846793005L + 1442695040888963407L;
			int px = x + (int) (((seed >>> 33) % 1000) * w / 1000);
			int py = y + (int) (((seed >>> 13) % 1000) * h / 1000);
			int r = 1 + (int) ((seed >>> 50) % 2);
			g.setComposite(AlphaComposite.getInstance(AlphaComposite.SRC_OVER, 0.25f + ((seed >>> 40) % 50) / 100f));
			g.setColor(c);
			g.fillOval(px, py, r * 2, r * 2);
		}
		g.setComposite(was);
	}

	static BasicStroke dashed()
	{
		return new BasicStroke(1f, BasicStroke.CAP_BUTT, BasicStroke.JOIN_MITER, 1f, new float[]{4f, 3f}, 0f);
	}
}

