/**
 * A death's picture: Death Log's own JPEG copy of RuneLite's death screenshot, in the plugin's folder as
 * pictures/&lt;the death's time in ms&gt;.jpg. RuneLite's own screenshot file is never touched.
 */
final class Pictures
{
	static final String DIR = "pictures";
	/** A death screenshot this close to a death (either side) is that death's: RuneLite takes it as you die. */
	static final long SAME_MS = 10_000L;
	/** Copies are kept at most this wide: big enough to look at, a few hundred KB each. */
	static final int KEEP_WIDTH = 1280;
	private static final float QUALITY = 0.85f;
	private static final Pattern FILE = Pattern.compile("^(\\d{10,})\\.jpg$");

	private Pictures()
	{
	}

	static String fileName(long at)
	{
		return at + ".jpg";
	}

	/** The death time a picture file is for; -1 = not one of ours. */
	static long timeOf(String fileName)
	{
		Matcher m = fileName == null ? null : FILE.matcher(fileName);
		return m != null && m.matches() ? Long.parseLong(m.group(1)) : -1;
	}

	/** {@code img} no wider than {@code max} (the same image when it already is), always plain RGB for JPEG. */
	static BufferedImage scaled(BufferedImage img, int max)
	{
		int w = img.getWidth(), h = img.getHeight();
		if (w > max)
		{
			h = Math.max(1, (int) Math.round(h * (max / (double) w)));
			w = max;
		}
		else if (img.getType() == BufferedImage.TYPE_INT_RGB)
		{
			return img;
		}
		BufferedImage out = new BufferedImage(w, h, BufferedImage.TYPE_INT_RGB);   // JPEG has no see-through
		Graphics2D g = out.createGraphics();
		g.setRenderingHint(RenderingHints.KEY_INTERPOLATION, RenderingHints.VALUE_INTERPOLATION_BILINEAR);
		g.drawImage(img, 0, 0, w, h, null);
		g.dispose();
		return out;
	}

	static void write(BufferedImage img, Filepath out) throws IOException
	{
		Iterator<ImageWriter> writers = ImageIO.getImageWritersByFormatName("jpg");
		if (!writers.hasNext())
		{
			throw new IOException("no JPEG writer");
		}
		ImageWriter w = writers.next();
		try (OutputStream raw = out.openOutputStream(); ImageOutputStream ios = ImageIO.createImageOutputStream(raw))
		{
			ImageWriteParam param = w.getDefaultWriteParam();
			param.setCompressionMode(ImageWriteParam.MODE_EXPLICIT);
			param.setCompressionQuality(QUALITY);
			w.setOutput(ios);
			w.write(null, new IIOImage(scaled(img, KEEP_WIDTH), null, null), param);
		}
		finally
		{
			w.dispose();
		}
	}

	/** A picture file read back; null = it can't be read. */
	static BufferedImage read(Filepath f) throws IOException
	{
		try (InputStream in = f.openInputStream())
		{
			return ImageIO.read(in);
		}
	}
}

