/**
 * Which raid room (or boss) a death was in, for the deaths where nothing was targeting you — the Great Olm, for one,
 * never targets you: its attacks are thrown, so a death to it has no attacker.
 * <ul>
 * <li>Chambers of Xeric: from where you died. A death's tile is saved as the raid's own map tile (a room keeps its
 * place on that map however the raid is laid out), and RuneLite's {@link InstanceTemplates} says which room each part
 * of that map is. The Olm's chamber is region {@value #OLM_REGION}.</li>
 * <li>Theatre of Blood, Tombs of Amascut (and any raid room the map doesn't name): the strongest monster near you
 * when you died, recorded live — see {@link #boss(String)}.</li>
 * </ul>
 */
final class RaidRooms
{
	/**
	 * The Great Olm's chamber. The user's two Chambers of Xeric Challenge Mode deaths on 2026-11-07 were here, 2 and
	 * 4 minutes before the raid's completion (its PB was saved at 22:33:29) — the Olm is the last room.
	 */
	static final int OLM_REGION = 12889;
	static final String COX = "Chambers of Xeric";

	private RaidRooms()
	{
	}

	/** The Chambers of Xeric room at a death's saved tile; null = not a room with a name (or not in the raid). */
	static String cox(int x, int y, int plane, int region)
	{
		if (region == OLM_REGION)
		{
			return "Great Olm";
		}
		for (InstanceTemplates t : InstanceTemplates.values())
		{
			if (t.getPlane() == plane && x >= t.getBaseX() && x < t.getBaseX() + t.getWidth()
				&& y >= t.getBaseY() && y < t.getBaseY() + t.getHeight())
			{
				return name(t);
			}
		}
		return null;
	}

	/** A room's name as players say it; null for the lobby, the start and the floor exits (no one dies to those). */
	static String name(InstanceTemplates t)
	{
		switch (t)
		{
			case RAIDS_SCAVENGERS:
			case RAIDS_SCAVENGERS2:
				return "Scavengers";
			case RAIDS_SHAMANS:
				return "Lizardman shamans";
			case RAIDS_VASA:
				return "Vasa Nistirio";
			case RAIDS_VANGUARDS:
				return "Vanguards";
			case RAIDS_ICE_DEMON:
				return "Ice demon";
			case RAIDS_THIEVING:
				return "Thieving room";
			case RAIDS_FARMING:
			case RAIDS_FARMING2:
				return "Farming room";
			case RAIDS_MUTTADILES:
				return "Muttadiles";
			case RAIDS_MYSTICS:
				return "Skeletal mystics";
			case RAIDS_TEKTON:
				return "Tekton";
			case RAIDS_TIGHTROPE:
				return "Tightrope";
			case RAIDS_GUARDIANS:
				return "Guardians";
			case RAIDS_VESPULA:
				return "Vespula";
			case RAIDS_CRABS:
				return "Crystal crabs";
			default:
				return null;
		}
	}

	/**
	 * A monster's name as the room it stands for: "Great Olm Left claw" / "Great Olm Right claw" → "Great Olm",
	 * "Tekton (enraged)" → "Tekton"; anything else as the game names it.
	 */
	static String boss(String npc)
	{
		if (npc == null)
		{
			return null;
		}
		if (npc.startsWith("Great Olm"))
		{
			return "Great Olm";
		}
		String s = npc.replaceFirst("\\s*\\([^)]*\\)$", "").trim();
		return s.isEmpty() ? null : s;
	}
}

