/**
 * ⭐ STATISTICS & GRAPHS (user, 2026-11-04: "i like statistics and graphs a lot"): deaths over time (days, weeks,
 * months), each boss's kills between deaths, the wave of each attempt at the wave fights, and when and how you die.
 */
final class StatsWindow extends JFrame
{
	private static final int W = 700;
	private static final Color DIM = new Color(0x9A, 0x9A, 0x9A);
	private static final ZoneId ZONE = ZoneId.systemDefault();

	private DeathLogPlugin.View view;
	private Theme theme = Theme.of(DeathLogConfig.Look.DASHBOARD);
	private final List<JComponent> pages = new ArrayList<>();
	private final List<JScrollPane> scrolls = new ArrayList<>();
	private final List<JLabel> notes = new ArrayList<>();
	private final List<JLabel> titles = new ArrayList<>();

	// Over time
	private DeathStats.Step step = DeathStats.Step.DAY;
	private final BarChart timeChart = new BarChart(400, 300);
	private final JLabel timeNote = note();
	// Bosses
	private final JComboBox<String> bossPick = new JComboBox<>();
	private final List<String> bossKeys = new ArrayList<>();
	private final JLabel bossNote = note();
	private final BarChart bossChart = new BarChart(400, 260);
	private final JLabel bossTable = note();
	// Wave fights
	private final JComboBox<String> wavePick = new JComboBox<>();
	private final JLabel waveNote = note();
	private final BarChart waveChart = new BarChart(400, 280);
	// Who & when
	private final Killers killers = new Killers();
	private final BarChart hourChart = new BarChart(400, 200);
	private final BarChart dayChart = new BarChart(400, 170);
	private final JLabel howNote = note();
	private boolean filling;

	StatsWindow(BufferedImage icon)
	{
		super("Death Log - statistics");
		setIconImage(icon);
		setDefaultCloseOperation(HIDE_ON_CLOSE);
		JTabbedPane tabs = new JTabbedPane();
		tabs.addTab("Over time", scroll(overTimeTab()));
		tabs.addTab("Bosses", scroll(bossesTab()));
		tabs.addTab("Wave fights", scroll(waveTab()));
		tabs.addTab("Who & when", scroll(howTab()));
		setContentPane(tabs);
		setSize(new Dimension(W + 30, 560));
	}

	/** The panel's theme: backgrounds, text and the charts' colours. */
	void theme(Theme t)
	{
		theme = t;
		for (JComponent p : pages)
		{
			p.setBackground(t.background);
		}
		for (JScrollPane s : scrolls)
		{
			s.getViewport().setBackground(t.background);
		}
		for (JLabel l : notes)
		{
			l.setForeground(t.dim);
		}
		for (JLabel l : titles)
		{
			l.setForeground(t.title);
		}
		for (BarChart c : new BarChart[]{timeChart, bossChart, waveChart, hourChart, dayChart})
		{
			c.theme(t);
		}
		if (view != null)
		{
			update(view);
		}
	}

	/** Show the newest numbers (Swing thread). */
	void update(DeathLogPlugin.View v)
	{
		view = v;
		drawTime();
		fillBosses();
		fillWaves();
		drawHow();
	}

	// ---- Over time ----

	private JComponent overTimeTab()
	{
		JPanel p = column();
		JPanel buttons = new JPanel(new FlowLayout(FlowLayout.LEFT, 4, 0));
		buttons.setOpaque(false);
		ButtonGroup group = new ButtonGroup();
		for (DeathStats.Step s : DeathStats.Step.values())
		{
			JToggleButton b = new JToggleButton(s.label + " (" + s.count + ")", s == step);
			b.addActionListener(e ->
			{
				step = s;
				drawTime();
			});
			group.add(b);
			buttons.add(b);
		}
		p.add(left(buttons));
		p.add(Box.createVerticalStrut(6));
		p.add(left(timeChart));
		p.add(Box.createVerticalStrut(6));
		p.add(left(timeNote));
		return p;
	}

	private void drawTime()
	{
		if (view == null)
		{
			return;
		}
		Object[] t = DeathStats.overTime(view.deaths, view.now, step, ZONE);
		String[] labels = (String[]) t[0];
		int[] counts = (int[]) t[1];
		double[] values = new double[counts.length];
		Color[] colors = new Color[counts.length];
		int sum = 0;
		int worst = 0;
		for (int i = 0; i < counts.length; i++)
		{
			values[i] = counts[i];
			sum += counts[i];
			worst = counts[i] > counts[worst] ? i : worst;
		}
		colors[counts.length - 1] = theme.accent;
		String unit = step == DeathStats.Step.DAY ? "day" : step == DeathStats.Step.WEEK ? "week" : "month";
		timeChart.set("Deaths per " + unit + " (the current one in red)", labels, values, colors, null);
		double avg = (double) sum / counts.length;
		timeChart.line(avg, String.format("average %.1f", avg));
		timeNote.setText(html(sum + " deaths in the last " + counts.length + " " + unit + "s · " + String.format("%.1f", avg)
			+ " a " + unit + (sum > 0 ? " · the worst " + unit + ": " + counts[worst] + " (" + labels[worst] + ")" : "")
			+ " · " + view.deaths.size() + " in all."));
	}

	// ---- Bosses ----

	private JComponent bossesTab()
	{
		JPanel p = column();
		bossPick.addActionListener(e -> drawBoss());
		p.add(left(row(label("Boss:"), bossPick)));
		p.add(Box.createVerticalStrut(6));
		p.add(left(bossNote));
		p.add(Box.createVerticalStrut(6));
		p.add(left(bossChart));
		bossChart.empty("No kill count seen for this boss yet - kill it once and the runs start.");
		p.add(Box.createVerticalStrut(10));
		p.add(left(label("Every boss")));
		p.add(left(bossTable));
		return p;
	}

	private void fillBosses()
	{
		List<DeathStats.BossRow> rows = DeathStats.bosses(view.deaths, view.killCounts);
		String was = bossPick.getSelectedIndex() >= 0 && bossPick.getSelectedIndex() < bossKeys.size()
			? bossKeys.get(bossPick.getSelectedIndex()) : null;
		filling = true;
		bossPick.removeAllItems();
		bossKeys.clear();
		StringBuilder t = new StringBuilder("<html><table cellpadding=2><tr><td><b>Boss</b></td><td><b>Deaths</b></td>"
			+ "<td><b>Kills</b></td><td><b>Death rate</b></td><td><b>Since last death</b></td><td><b>Best run</b></td>"
			+ "<td><b>Best wave</b></td></tr>");
		for (DeathStats.BossRow r : rows)
		{
			bossKeys.add(r.boss);
			bossPick.addItem(Bosses.display(r.boss));
			t.append("<tr><td>").append(esc(Bosses.display(r.boss))).append("</td><td>").append(r.deaths)
				.append("</td><td>").append(r.kills >= 0 ? String.valueOf(r.kills) : "-")
				.append("</td><td>").append(r.kills >= 0 ? String.format("%.1f%%", r.deathRate() * 100) : "-")
				.append("</td><td>").append(r.sinceDeath >= 0 ? String.valueOf(r.sinceDeath) : "-")
				.append("</td><td>").append(r.bestRun >= 0 ? String.valueOf(r.bestRun) : "-")
				.append("</td><td>").append(r.bestWave > 0 ? String.valueOf(r.bestWave) : "-").append("</td></tr>");
		}
		bossTable.setText(rows.isEmpty() ? "No boss deaths or kill counts yet." : t.append("</table></html>").toString());
		int keep = was == null ? 0 : Math.max(0, bossKeys.indexOf(was));
		if (!bossKeys.isEmpty())
		{
			bossPick.setSelectedIndex(keep);
		}
		filling = false;
		drawBoss();
	}

	private void drawBoss()
	{
		if (filling || view == null)
		{
			return;
		}
		int i = bossPick.getSelectedIndex();
		if (i < 0 || i >= bossKeys.size())
		{
			bossNote.setText("No boss deaths or kill counts yet.");
			bossChart.set("Kills between deaths", new String[0], new double[0], null, null);
			return;
		}
		String boss = bossKeys.get(i);
		DeathStats.BossRow row = null;
		for (DeathStats.BossRow r : DeathStats.bosses(view.deaths, view.killCounts))
		{
			row = r.boss.equals(boss) ? r : row;
		}
		List<int[]> runs = DeathStats.runSeries(view.deaths, view.killCounts, boss);
		List<Death> deaths = new ArrayList<>();
		for (Death d : view.deaths)
		{
			if (boss.equals(d.boss))
			{
				deaths.add(d);
			}
		}
		SimpleDateFormat day = new SimpleDateFormat("d MMM");
		int n = runs.size();
		String[] labels = new String[n];
		double[] values = new double[n];
		Color[] colors = new Color[n];
		String[] tips = new String[n];
		int best = -1;
		for (int k = 0; k < n; k++)
		{
			int run = runs.get(k)[0];
			values[k] = Math.max(0, run);
			best = Math.max(best, run);
			if (k < deaths.size())
			{
				Death d = deaths.get(k);
				labels[k] = day.format(new Date(d.at));
				tips[k] = (run >= 0 ? run + " kills, then " : "Kills not known, then ") + "died " + day.format(new Date(d.at))
					+ " to " + d.killedBy();
			}
			else
			{
				labels[k] = "now";
				colors[k] = theme.good;
				tips[k] = run + " kills since your last death (still going)";
			}
		}
		bossChart.set("Kills between deaths - " + Bosses.display(boss) + " (green: the run you are on)", labels, values, colors, tips);
		bossChart.line(best > 0 ? best : -1, best > 0 ? "best " + best : null);
		if (row != null)
		{
			bossNote.setText(html(row.deaths + (row.deaths == 1 ? " death" : " deaths")
				+ (row.kills >= 0 ? " · " + row.kills + (row.kills == 1 ? " kill" : " kills") + " since Death Log first saw your kill count (" + row.killCount
				+ " now) · " + String.format("%.1f%%", row.deathRate() * 100) + " of attempts ended in a death" : "")
				+ (row.sinceDeath >= 0 ? " · " + row.sinceDeath + (row.sinceDeath == 1 ? " kill" : " kills") + " since your last death, best " + row.bestRun : "")
				+ (row.bestWave > 0 ? " · best wave " + row.bestWave : "")));
		}
	}

	// ---- Wave fights ----

	private JComponent waveTab()
	{
		JPanel p = column();
		wavePick.addActionListener(e -> drawWave());
		p.add(left(row(label("Fight:"), wavePick)));
		p.add(Box.createVerticalStrut(6));
		p.add(left(waveNote));
		p.add(Box.createVerticalStrut(6));
		p.add(left(waveChart));
		waveChart.empty("No wave-fight deaths yet (the Inferno, the Fight Caves).");
		return p;
	}

	private void fillWaves()
	{
		Object was = wavePick.getSelectedItem();
		filling = true;
		wavePick.removeAllItems();
		for (String a : DeathStats.waveAreas(view.deaths))
		{
			wavePick.addItem(a);
		}
		if (was != null)
		{
			wavePick.setSelectedItem(was);
		}
		filling = false;
		drawWave();
	}

	private void drawWave()
	{
		if (filling || view == null)
		{
			return;
		}
		Object pick = wavePick.getSelectedItem();
		if (pick == null)
		{
			waveNote.setText(html("Every death at the Inferno or the Fight Caves is a bar here, as high as the wave you "
				+ "reached - watch them climb."));
			waveChart.set("Wave reached, each attempt", new String[0], new double[0], null, null);
			return;
		}
		String area = pick.toString();
		List<Death> tries = DeathStats.waveDeaths(view.deaths, area);
		SimpleDateFormat day = new SimpleDateFormat("d MMM");
		int n = tries.size();
		String[] labels = new String[n];
		double[] values = new double[n];
		Color[] colors = new Color[n];
		String[] tips = new String[n];
		int best = 0;
		for (Death d : tries)
		{
			best = Math.max(best, d.wave);
		}
		int lastFive = 0;
		for (int k = 0; k < n; k++)
		{
			Death d = tries.get(k);
			labels[k] = "#" + (k + 1);
			values[k] = d.wave;
			colors[k] = d.wave == best ? theme.good : k == n - 1 ? theme.accent : null;
			tips[k] = "Attempt " + (k + 1) + " · " + new SimpleDateFormat("EEE d MMM HH:mm").format(new Date(d.at))
				+ " · wave " + d.wave + " · " + d.killedBy();
			lastFive += k >= n - 5 ? d.wave : 0;
		}
		waveChart.set("Wave reached, each attempt - " + area + " (green: your best, red: the latest)", labels, values, colors, tips);
		waveChart.line(best, "best wave " + best);
		String kcName = Bosses.WAVE_AREAS.get(area);
		int[] kc = kcName == null ? null : view.killCounts.get(kcName);
		waveNote.setText(html(n + (n == 1 ? " attempt" : " attempts") + " ended in a death · best wave " + best
			+ String.format(" · the last %d averaged wave %.1f", Math.min(5, n), (double) lastFive / Math.min(5, n))
			+ (kc != null ? " · completed " + (kc[1] - kc[0] + 1) + " since Death Log first saw your kill count" : "")
			+ (n > 0 ? " · first " + day.format(new Date(tries.get(0).at)) : "")));
	}

	// ---- When & how ----

	private JComponent howTab()
	{
		JPanel p = column();
		p.add(left(killers));
		p.add(Box.createVerticalStrut(8));
		p.add(left(hourChart));
		p.add(Box.createVerticalStrut(8));
		p.add(left(dayChart));
		p.add(Box.createVerticalStrut(8));
		p.add(left(howNote));
		return p;
	}

	private void drawHow()
	{
		int[] h = DeathStats.byHour(view.deaths, ZONE);
		String[] hl = new String[24];
		double[] hv = new double[24];
		String[] ht = new String[24];
		for (int i = 0; i < 24; i++)
		{
			hl[i] = clock(i);
			hv[i] = h[i];
			ht[i] = clock(i) + " to " + clock((i + 1) % 24) + ": " + h[i] + (h[i] == 1 ? " death" : " deaths");
		}
		hourChart.set("Deaths by time of day", hl, hv, null, ht);
		int[] d = DeathStats.byWeekday(view.deaths, ZONE);
		String[] dl = {"Mon", "Tue", "Wed", "Thu", "Fri", "Sat", "Sun"};
		double[] dv = new double[7];
		for (int i = 0; i < 7; i++)
		{
			dv[i] = d[i];
		}
		dayChart.set("Deaths by the day of the week", dl, dv, null, null);
		killers.set(DeathStats.top(view.deaths, x -> x.from != null ? null : x.who(), 10));
		StringBuilder s = new StringBuilder("<html>");
		s.append("<b>How</b> (the last damage before each death): ");
		boolean first = true;
		for (Map.Entry<String, Integer> e : DeathStats.top(view.deaths, x -> x.from != null ? null
			: x.cause == null ? "nothing seen" : x.cause, 10))
		{
			s.append(first ? "" : " · ").append(esc(e.getKey())).append(" ").append(e.getValue());
			first = false;
		}
		s.append("<br><br><b>Hardest killing blows</b>");
		for (Death x : DeathStats.hardestHits(view.deaths, 5))
		{
			s.append("<br>").append(x.lastHit).append(" - ").append(esc(x.killedBy())).append(", ").append(esc(x.place()))
				.append(", ").append(new SimpleDateFormat("d MMM yyyy").format(new Date(x.at)));
		}
		howNote.setText(s.append("</html>").toString());
	}

	/** "Who killed you most": a bar per killer, the longest first, with its count. */
	private final class Killers extends JComponent
	{
		private static final int ROW = 20;
		private List<Map.Entry<String, Integer>> rows = new ArrayList<>();

		Killers()
		{
			setPreferredSize(new Dimension(400, 40));
		}

		void set(List<Map.Entry<String, Integer>> r)
		{
			rows = r;
			setPreferredSize(new Dimension(400, 30 + Math.max(1, r.size()) * ROW + 8));
			setMaximumSize(new Dimension(Integer.MAX_VALUE, getPreferredSize().height));
			revalidate();
			repaint();
		}

		@Override
		protected void paintComponent(java.awt.Graphics g0)
		{
			java.awt.Graphics2D g = (java.awt.Graphics2D) g0.create();
			Draw.smooth(g);
			g.setColor(theme.cardFill);
			g.fillRect(0, 0, getWidth(), getHeight());
			g.setFont(FontManager.getRunescapeBoldFont());
			g.setColor(theme.title);
			g.drawString("Who killed you most", 8, 16);
			g.setFont(FontManager.getRunescapeSmallFont());
			if (rows.isEmpty())
			{
				g.setColor(theme.dim);
				g.drawString("Nothing yet.", 8, 40);
				g.dispose();
				return;
			}
			int max = rows.get(0).getValue();
			int nameW = 170;
			int barX = 8 + nameW + 8;
			int barW = getWidth() - barX - 50;
			for (int i = 0; i < rows.size(); i++)
			{
				Map.Entry<String, Integer> e = rows.get(i);
				int y = 30 + i * ROW;
				g.setColor(theme.text);
				g.drawString(Draw.fit(g.getFontMetrics(), e.getKey(), nameW), 8, y + 12);
				int len = Math.max(3, barW * e.getValue() / Math.max(1, max));
				g.setColor(i == 0 ? theme.accent : theme.bar);
				g.fillRect(barX, y + 3, len, ROW - 8);
				g.setColor(theme.text);
				g.drawString(String.valueOf(e.getValue()), barX + len + 6, y + 12);
			}
			g.dispose();
		}
	}

	/** An hour of the day as a clock reads it: 0 -> "12am", 13 -> "1pm". */
	static String clock(int hour)
	{
		int h = hour % 12 == 0 ? 12 : hour % 12;
		return h + (hour < 12 ? "am" : "pm");
	}

	// ---- helpers ----

	/** A tab's page: as wide as the window (never a sideways scroll), as tall as it needs. */
	private static final class Page extends JPanel implements Scrollable
	{
		@Override
		public Dimension getPreferredScrollableViewportSize()
		{
			return getPreferredSize();
		}

		@Override
		public int getScrollableUnitIncrement(Rectangle r, int orientation, int direction)
		{
			return 16;
		}

		@Override
		public int getScrollableBlockIncrement(Rectangle r, int orientation, int direction)
		{
			return 160;
		}

		@Override
		public boolean getScrollableTracksViewportWidth()
		{
			return true;
		}

		@Override
		public boolean getScrollableTracksViewportHeight()
		{
			// fills the window when it is shorter (the dark background goes to the bottom); scrolls when taller
			return getParent() instanceof JViewport && getParent().getHeight() > getPreferredSize().height;
		}
	}

	private JPanel column()
	{
		JPanel p = new Page();
		pages.add(p);
		p.setLayout(new BoxLayout(p, BoxLayout.Y_AXIS));
		p.setBackground(ColorScheme.DARK_GRAY_COLOR);
		p.setBorder(new EmptyBorder(10, 10, 10, 10));
		return p;
	}

	private JScrollPane scroll(JComponent c)
	{
		JScrollPane s = new JScrollPane(c);
		scrolls.add(s);
		s.setBorder(BorderFactory.createEmptyBorder());
		s.getViewport().setBackground(ColorScheme.DARK_GRAY_COLOR);
		s.getVerticalScrollBar().setUnitIncrement(16);
		return s;
	}

	/** Left-aligned; it may grow sideways, never taller than it wants (no gaps between the parts). */
	private static JComponent left(JComponent c)
	{
		c.setAlignmentX(Component.LEFT_ALIGNMENT);
		if (!(c instanceof JLabel))             // a label's text comes later: it keeps its own size
		{
			c.setMaximumSize(new Dimension(Integer.MAX_VALUE, c.getPreferredSize().height));
		}
		return c;
	}

	private static JPanel row(JComponent a, JComponent b)
	{
		JPanel p = new JPanel(new BorderLayout(6, 0));
		p.setOpaque(false);
		p.add(a, BorderLayout.WEST);
		p.add(b, BorderLayout.CENTER);
		p.setMaximumSize(new Dimension(360, 28));
		return p;
	}

	private JLabel label(String text)
	{
		JLabel l = new JLabel(text);
		titles.add(l);
		l.setForeground(Color.WHITE);
		l.setFont(FontManager.getRunescapeBoldFont());
		return l;
	}

	private JLabel note()
	{
		JLabel l = new JLabel();
		notes.add(l);
		l.setForeground(DIM);
		l.setFont(FontManager.getRunescapeSmallFont());
		return l;
	}

	private static String html(String s)
	{
		return "<html><div style='width:" + (W - 160) + "px'>" + esc(s) + "</div></html>";
	}

	private static String esc(String s)
	{
		return s.replace("&", "&amp;").replace("<", "&lt;").replace(">", "&gt;");
	}
}

