/**
 * ⭐ THEMES (user, 2026-11-04: "is it possible to have there be themes????? we could have these three and maybe some
 * more"). Everything the panel and the graphs draw with: colours, card and header shapes, the top (hero) style.
 */
final class Theme
{
	/** The top of the panel. */
	enum Hero
	{
		/** A gradient card: the total, a 14-day line, an "alive" tag. */
		CARD,
		/** The total carved on a tombstone. */
		TOMBSTONE,
		/** The game's own interface: a title bar and a bevelled box. */
		BEVEL
	}

	/** How cards are drawn. */
	enum Card
	{
		ROUND, STONE, BEVEL, FLAT
	}

	/** How section headers are drawn. */
	enum Header
	{
		LINE, SKULL_LINE, CENTRED
	}

	Hero hero = Hero.CARD;
	Card card = Card.ROUND;
	Header header = Header.LINE;
	int radius = 12;

	Color background;
	Color cardFill;
	/** A thin outline round each card; null = none. */
	Color cardEdge;
	/** Bevel light / dark (the game's look). */
	Color bevelLight;
	Color bevelDark;
	Color text = Color.WHITE;
	Color dim;
	/** Deaths: numbers, the latest bar, accents. */
	Color accent;
	/** The kill runs and bests. */
	Color good;
	/** Titles (the game's orange in Old School). */
	Color title = Color.WHITE;
	/** The big numbers; null = text. */
	Color number;
	/** Small tags, bar tracks, buttons. */
	Color chip;
	Color bar;
	/** The top card's gradient. */
	Color heroTop;
	Color heroBottom;
	/** The three counter tiles' top stripe; null = none. */
	Color[] tileStripes;
	/** Text drawn with the game's black shadow. */
	boolean shadow;
	/** Numbers drawn with a soft glow (Ectoplasm, Infernal). */
	Color glow;
	/** Little dots of light in the top card (Infernal embers, Ectoplasm motes); null = none. */
	Color motes;
	/** Faint stone blocks behind everything (Old School). */
	Color blocks;
	boolean upperCaseHeaders;
	/** Molten rock: the top card is basalt with glowing cracks over a lava pool; cards glow at their lower edge. */
	boolean lava;

	static Theme of(DeathLogConfig.Look look)
	{
		Theme t = new Theme();
		switch (look)
		{
			case GRAVESTONE:
				t.hero = Hero.TOMBSTONE;
				t.card = Card.STONE;
				t.header = Header.SKULL_LINE;
				t.radius = 6;
				t.background = new Color(0x17, 0x17, 0x19);
				t.cardFill = new Color(0x26, 0x27, 0x2A);
				t.cardEdge = new Color(0x3A, 0x3B, 0x3F);
				t.dim = new Color(0x95, 0x95, 0x98);
				t.accent = new Color(0xC8, 0x3A, 0x2E);
				t.good = new Color(0x6E, 0xA0, 0x4E);
				t.title = new Color(0xD8, 0xD8, 0xD8);
				t.chip = new Color(0x33, 0x34, 0x37);
				t.bar = new Color(0x7A, 0x2A, 0x24);
				t.heroTop = new Color(0x86, 0x88, 0x8D);
				t.heroBottom = new Color(0x55, 0x57, 0x5C);
				t.upperCaseHeaders = true;
				break;
			case OLD_SCHOOL:
				t.hero = Hero.BEVEL;
				t.card = Card.BEVEL;
				t.header = Header.CENTRED;
				t.radius = 0;
				t.background = new Color(0x3E, 0x35, 0x29);
				t.cardFill = new Color(0x2B, 0x24, 0x1C);
				t.bevelLight = new Color(0x5C, 0x4F, 0x3D);
