				t.title = new Color(0xFF, 0x98, 0x1F);
				t.number = new Color(0xFF, 0xFF, 0x00);
				t.chip = new Color(0x4A, 0x3E, 0x2F);
				t.bar = new Color(0xB8, 0x60, 0x10);
				t.shadow = true;
				t.blocks = new Color(0x45, 0x3B, 0x2E);
				break;
			case ECTOPLASM:
				t.background = new Color(0x0D, 0x12, 0x13);
				t.cardFill = new Color(0x15, 0x1F, 0x21);
				t.cardEdge = new Color(0x21, 0x36, 0x36);
				t.dim = new Color(0x7F, 0x9C, 0x98);
				t.accent = new Color(0x6E, 0xF0, 0xB4);
				t.good = new Color(0xB4, 0x8C, 0xFF);
				t.title = new Color(0xCF, 0xFF, 0xEC);
				t.number = new Color(0xB8, 0xFF, 0xDF);
				t.chip = new Color(0x1E, 0x2E, 0x30);
				t.bar = new Color(0x2E, 0x7A, 0x5E);
				t.heroTop = new Color(0x1E, 0x3A, 0x36);
				t.heroBottom = new Color(0x0F, 0x18, 0x1A);
				t.tileStripes = new Color[]{new Color(0x6E, 0xF0, 0xB4), new Color(0x5C, 0xC8, 0xE6), new Color(0xB4, 0x8C, 0xFF)};
				t.glow = new Color(0x6E, 0xF0, 0xB4);
				t.motes = new Color(0x9E, 0xFF, 0xD6);
				break;
			case INFERNAL:
				t.background = new Color(0x12, 0x0A, 0x08);
				t.cardFill = new Color(0x1F, 0x12, 0x0E);
				t.cardEdge = new Color(0x4A, 0x22, 0x10);
				t.dim = new Color(0xB0, 0x8C, 0x78);
				t.accent = new Color(0xFF, 0x6A, 0x1A);
				t.good = new Color(0xFF, 0xC8, 0x3C);
				t.title = new Color(0xFF, 0xE0, 0xC0);
				t.number = new Color(0xFF, 0xB0, 0x40);
				t.chip = new Color(0x2E, 0x1A, 0x12);
				t.bar = new Color(0x8A, 0x32, 0x0E);
				t.heroTop = new Color(0x7A, 0x22, 0x06);
				t.heroBottom = new Color(0x1A, 0x0A, 0x06);
				t.tileStripes = new Color[]{new Color(0xFF, 0x6A, 0x1A), new Color(0xFF, 0xA0, 0x2A), new Color(0xFF, 0xD0, 0x4A)};
				t.glow = new Color(0xFF, 0x70, 0x20);
				t.motes = new Color(0xFF, 0xC0, 0x60);
				t.heroTop = new Color(0x2A, 0x14, 0x0C);
				t.heroBottom = new Color(0x12, 0x08, 0x05);
				t.lava = true;
				break;
			case PLAIN:
				t.card = Card.FLAT;
				t.radius = 0;
				t.background = new Color(0x28, 0x28, 0x28);
				t.cardFill = new Color(0x1E, 0x1E, 0x1E);
				t.dim = new Color(0x9A, 0x9A, 0x9A);
				t.accent = new Color(0xDC, 0x8A, 0x00);
				t.good = new Color(0x4C, 0xC0, 0x5A);
				t.chip = new Color(0x32, 0x32, 0x32);
				t.bar = new Color(0x8A, 0x5A, 0x10);
				t.heroTop = new Color(0x1E, 0x1E, 0x1E);
				t.heroBottom = new Color(0x1E, 0x1E, 0x1E);
				break;
			case DASHBOARD:
			default:
				t.background = new Color(0x1B, 0x1B, 0x1E);
				t.cardFill = new Color(0x27, 0x27, 0x2C);
				t.dim = new Color(0x8E, 0x8E, 0x99);
				t.accent = new Color(0xF0, 0x4E, 0x45);
				t.good = new Color(0x3D, 0xD6, 0x8C);
				t.chip = new Color(0x34, 0x34, 0x3B);
				t.bar = new Color(0x6A, 0x2A, 0x2E);
				t.heroTop = new Color(0x7A, 0x1F, 0x22);
				t.heroBottom = new Color(0x2E, 0x14, 0x1A);
				t.tileStripes = new Color[]{new Color(0xF0, 0x4E, 0x45), new Color(0xF5, 0xA6, 0x23), new Color(0x9B, 0x7B, 0xF2)};
				break;
		}
		return t;
	}

	/** The colour for big numbers. */
	Color number()
	{
		return number != null ? number : text;
	}
}

