/** Offline: areas, bosses and kill counts, the counters, the killer pick, the CSV. */
public class DeathLogTest
{
	private static final ZoneId Z = ZoneId.of("UTC");

	@Test
	public void areasFromRuneLitesTable()
	{
		Areas a = Areas.load();
		assertTrue("the table loads: " + a.size(), a.size() > 700);
		assertEquals("The Inferno", a.of(2271, 5330, 0).name);              // region 9043
		assertEquals("MINIGAMES", a.of(2271, 5330, 0).type);
		assertEquals("Tzhaar Fight Caves", a.of(2400, 5088, 0).name);       // region 9551
		Areas.Place wild = a.of(3100, 3700, 0);                              // north of Edgeville
		assertEquals(23, wild.wildy);
		assertEquals(0, Areas.wildernessLevel(3222, 3218));                   // Lumbridge
		assertEquals(1, Areas.wildernessLevel(3100, 3520));
		assertEquals(1, Areas.wildernessLevel(3100, 9925));                   // a Wilderness dungeon
	}

	@Test
	public void areasSkipBadRows() throws Exception
	{
		Areas a = new Areas();
		a.read(new BufferedReader(new StringReader("# comment\n9043\tThe Inferno\tMINIGAMES\nnot\ta\trow\n12\tshort\n")));
		assertEquals(1, a.size());
	}

	@Test
	public void killCountMessages()
	{
		Object[] k = Bosses.killCount("Your TzKal-Zuk kill count is: <col=ff0000>3</col>.");
		assertEquals("TzKal-Zuk", k[0]);
		assertEquals(3, k[1]);
		k = Bosses.killCount("Your completed Theatre of Blood count is: <col=ff0000>1,204</col>.");
		assertEquals("Theatre of Blood", k[0]);
		assertEquals(1204, k[1]);
		assertNull(Bosses.killCount("Your Varrock Rooftop lap count is: <col=ff0000>50</col>."));
		assertNull(Bosses.killCount("Welcome to Old School RuneScape."));
	}

	@Test
	public void whichBoss()
	{
		Bosses b = new Bosses();
		assertEquals("TzKal-Zuk", b.bossOf("The Inferno", "MINIGAMES", "Jal-Xil"));     // anything kills you "at the Inferno"
		assertEquals("Theatre of Blood", b.bossOf("Theatre of Blood", "RAIDS", "Nylocas Hagios"));
		assertEquals("Vorkath", b.bossOf("Vorkath", "BOSSES", "Vorkath"));
		assertEquals("Grotesque Guardians", b.bossOf("Slayer Tower", "DUNGEONS", "Dusk"));
		assertEquals("Leviathan", b.bossOf(null, null, "The Leviathan"));
		assertEquals("Barrows Chests", b.bossOf("Barrows", "MINIGAMES", "Dharok the Wretched"));
		assertNull(b.bossOf("Varrock", "CITIES", "Guard"));
		assertNull(b.bossOf(null, null, "Brutal black dragon"));
		b.learn("Brutal black dragon");                                                 // seen in a kill-count message
		assertEquals("Brutal black dragon", b.bossOf(null, null, "Brutal black dragon"));
		assertTrue(Bosses.countsFor("Dagannoth Rex", "Dagannoth Kings"));
		assertTrue(Bosses.countsFor("Theatre of Blood Hard Mode", "Theatre of Blood"));
		assertTrue(Bosses.countsFor("Barrows chest", "Barrows Chests"));
		assertTrue(!Bosses.countsFor("Vorkath", "Zulrah"));
	}

	@Test
	public void counters()
	{
		long now = 1_800_000_000_000L;
		List<Death> all = new ArrayList<>();
		for (long ago : new long[]{3 * 86_400_000L, 2 * 3_600_000L, 40 * 60_000L, 5 * 60_000L})
		{
			all.add(death(now - ago, "Jal-Xil", "The Inferno", "TzKal-Zuk", 10));
		}
		assertEquals(2, DeathStats.since(all, now - DeathStats.HOUR_MS));          // last hour
		assertEquals(4, DeathStats.since(all, 0));
		int[] days = DeathStats.perDay(all, now, 14, Z);
		assertEquals(14, days.length);
		int sum = 0;
		for (int d : days)
		{
			sum += d;
		}
		assertEquals(4, sum);
		assertEquals(3 * 86_400_000L - 2 * 3_600_000L, DeathStats.longestAlive(all, now));
		assertEquals("2h 05m", DeathStats.duration(125 * 60_000L));
		assertEquals("3d 4h", DeathStats.duration((3 * 24 + 4) * 3_600_000L));
		assertEquals(2.0, DeathStats.perHour(4, 2 * DeathStats.HOUR_MS), 1e-9);
	}

	@Test
	public void bossRowsWithKillCounts()
	{
		List<Death> all = new ArrayList<>();
		all.add(death(1, "Jal-Xil", "The Inferno", "TzKal-Zuk", 31));
		all.add(death(2, "Jal-Zek", "The Inferno", "TzKal-Zuk", 18));
		all.add(death(3, "Vorkath", "Vorkath", "Vorkath", 0));
		Map<String, int[]> kc = new HashMap<>();
		kc.put("Vorkath", new int[]{800, 819});            // 20 kills since the plugin first saw it
		kc.put("Zulrah", new int[]{50, 50});               // killed, never died to
		kc.put("Lunar Chest", new int[]{5, 9});            // not a boss: no row
		List<DeathStats.BossRow> rows = DeathStats.bosses(all, kc);
		assertEquals(3, rows.size());
		DeathStats.BossRow inferno = rows.get(0);
		assertEquals("TzKal-Zuk", inferno.boss);
		assertEquals(2, inferno.deaths);
		assertEquals(31, inferno.bestWave);
		assertEquals(-1, inferno.kills);
		DeathStats.BossRow vork = rows.get(1);
		assertEquals(20, vork.kills);
		assertEquals(1.0 / 21, vork.deathRate(), 1e-9);
		assertEquals("Zulrah", rows.get(2).boss);
		assertEquals(0, rows.get(2).deaths);
	}

	@Test
	public void theKiller()
	{
		List<Attackers.Attacker> a = new ArrayList<>();
		Attackers.Attacker bat = new Attackers.Attacker("Jal-MejRah", 7692, 85, false, 100);
		Attackers.Attacker mager = new Attackers.Attacker("Jal-Zek", 7699, 490, false, 99);
		Attackers.Attacker old = new Attackers.Attacker("Jal-Ak", 7693, 165, false, 70);   // 30 ticks ago: not counted
		bat.onYou = true;
		mager.onYou = true;
		a.add(bat);
		a.add(mager);
		a.add(old);
		List<Attackers.Attacker> on = Attackers.atDeath(a, 100);
		assertEquals(2, on.size());
		assertEquals("Jal-Zek", on.get(0).name);           // on you, the strongest
		mager.onYou = false;
		mager.lastTick = 95;
		assertEquals("Jal-MejRah", Attackers.atDeath(a, 100).get(0).name);   // still on you beats stronger but gone
	}

	@Test
	public void wordsAndCsv()
	{
		Death d = death(1_800_000_000_000L, "Zulrah", "Zul-Andra", "Zulrah", 0);
		d.cause = "venom";
		d.killerLevel = 725;
		assertEquals("Venom, fighting Zulrah (level 725)", d.killedBy());
		d.cause = "hit";
		assertEquals("Zulrah (level 725)", d.killedBy());
		Death w = death(1, null, "Wilderness level 20", null, 0);
		w.wildy = 20;
		assertEquals("Wilderness level 20", w.place());
		Death inf = death(1, "Jal-Xil", "The Inferno", "TzKal-Zuk", 31);
		assertEquals("The Inferno, wave 31", inf.place());
		d.note = "lagged, \"really\"";
		String csv = DeathCsv.of(List.of(d));
		assertTrue(csv.startsWith(DeathCsv.HEADER + "\n1,"));
		assertTrue(csv.contains("\"lagged, \"\"really\"\"\""));
		assertEquals("2026-01-01_00-00-00", DeathLogPlugin.safe("2026-01-01_00-00-00"));
		assertEquals("rsprofile.a_b", DeathLogPlugin.safe("rsprofile.a/b"));
	}

	@Test
	public void importFromScreenshots()
	{
		long t = DeathImport.timeOf("Death 2026-11-04_18-22-11.png", Z);
		assertEquals(java.time.Instant.parse("2026-11-04T18:22:11Z").toEpochMilli(), t);
		assertEquals(t, DeathImport.timeOf("Death 2026-11-04_18-22-11(1).png", Z));    // a second one that second
		assertEquals(-1, DeathImport.timeOf("Death Zezima 2026-11-04_18-22-11.png", Z)); // a friend's death
		assertEquals(-1, DeathImport.timeOf("Level up 2026-11-04_18-22-11.png", Z));
		assertEquals(-1, DeathImport.timeOf("Death 2026-13-45_99-00-00.png", Z));
		List<Death> known = new ArrayList<>();
		known.add(death(t + 30_000, "Jal-Xil", "The Inferno", "TzKal-Zuk", 31));       // recorded live, 30 s off
		List<Death> add = DeathImport.fresh(List.of(t, t + 1_000, t + 3_600_000L), known);
		assertEquals(1, add.size());                       // the live one and its "(1)" twin are skipped
		assertEquals(t + 3_600_000L, add.get(0).at);
		assertEquals(DeathImport.FROM_SCREENSHOT, add.get(0).from);
		assertEquals("From before Death Log", add.get(0).killedBy());
		known.addAll(add);
		assertEquals(0, DeathImport.fresh(List.of(t, t + 3_600_000L), known).size());   // importing again adds none
	}

	@Test
	public void killsSinceLastDeath()
	{
		Map<String, int[]> kc = new HashMap<>();
		kc.put("Vorkath", new int[]{800, 900});           // first seen 800 (that kill counts), 900 now
		List<Death> all = new ArrayList<>();
		Death a = death(1, "Vorkath", "Vorkath", "Vorkath", 0);
		a.killCount = 820;                                 // 21 kills (800-820), then died
		Death b = death(2, "Vorkath", "Vorkath", "Vorkath", 0);
		b.killCount = 850;                                 // 30 more, then died
		all.add(a);
		all.add(b);
		int[] r = DeathStats.runs(all, kc, "Vorkath");
		assertEquals(50, r[0]);                            // 851-900 since the last death
		assertEquals(50, r[1]);                            // the best run, this one included
		assertEquals(30, r[2]);                            // the best before this run
		List<int[]> series = DeathStats.runSeries(all, kc, "Vorkath");
		assertEquals(3, series.size());
		assertEquals(21, series.get(0)[0]);
		assertEquals(30, series.get(1)[0]);
		assertEquals(50, series.get(2)[0]);
		// a death before any kill count was seen: the run starts at the first one seen
		Map<String, int[]> z = new HashMap<>();
		z.put("Zulrah", new int[]{10, 15});
		Death c = death(3, "Zulrah", "Zul-Andra", "Zulrah", 0);
		assertEquals(6, DeathStats.runs(List.of(c), z, "Zulrah")[0]);
		assertEquals(-1, DeathStats.runs(List.of(c), new HashMap<>(), "Zulrah")[0]);
		// the chat lines
		assertTrue(DeathLogPlugin.streakLine("Vorkath", new int[]{48, 112, 112}, true).contains("48 kills since your last death (best 112)"));
		assertTrue(DeathLogPlugin.streakLine("Vorkath", new int[]{113, 113, 112}, true).contains("new best!"));
		assertTrue(!DeathLogPlugin.streakLine("Vorkath", new int[]{114, 114, 112}, true).contains("new best!"));   // once only
		assertTrue(DeathLogPlugin.streakLine("Zulrah", new int[]{12, 12, -1}, false).contains("12 kills, no deaths yet"));
	}

	@Test
	public void graphsData()
	{
		long now = java.time.ZonedDateTime.of(2026, 11, 4, 20, 0, 0, 0, Z).toInstant().toEpochMilli();
		List<Death> all = new ArrayList<>();
		all.add(death(now - 3_600_000L, "a", null, null, 0));               // today 19:00
		all.add(death(now - 25 * 3_600_000L, "b", null, null, 0));          // yesterday 19:00
		all.add(death(now - 40L * 86_400_000L, "c", null, null, 0));        // 25 Sep
		Object[] days = DeathStats.overTime(all, now, DeathStats.Step.DAY, Z);
		int[] d = (int[]) days[1];
		assertEquals(30, d.length);
		assertEquals(1, d[29]);
		assertEquals(1, d[28]);
		assertEquals("4 Nov", ((String[]) days[0])[29]);
		int[] months = (int[]) DeathStats.overTime(all, now, DeathStats.Step.MONTH, Z)[1];
		assertEquals(2, months[11]);                                         // November
		assertEquals(1, months[9]);                                          // September
		assertEquals(2, DeathStats.byHour(all, Z)[19]);
		assertEquals(3, DeathStats.byWeekday(all, Z)[0] + DeathStats.byWeekday(all, Z)[1] + DeathStats.byWeekday(all, Z)[2]
			+ DeathStats.byWeekday(all, Z)[3] + DeathStats.byWeekday(all, Z)[4] + DeathStats.byWeekday(all, Z)[5]
			+ DeathStats.byWeekday(all, Z)[6]);
		List<Death> inf = new ArrayList<>();
		inf.add(death(1, "Jal-Zek", "The Inferno", "TzKal-Zuk", 18));
		inf.add(death(2, "Jal-Xil", "The Inferno", "TzKal-Zuk", 31));
		inf.add(death(3, "Guard", "Varrock", null, 0));
		assertEquals(List.of("The Inferno"), DeathStats.waveAreas(inf));
		assertEquals(2, DeathStats.waveDeaths(inf, "The Inferno").size());
		assertEquals("12am", StatsWindow.clock(0));
		assertEquals("11am", StatsWindow.clock(11));
		assertEquals("12pm", StatsWindow.clock(12));
		assertEquals("7pm", StatsWindow.clock(19));
		assertEquals(7.0, BarChart.nice(7), 1e-9);
		assertEquals(40.0, BarChart.nice(31), 1e-9);
		assertEquals(70.0, BarChart.nice(66), 1e-9);
	}

	@Test
	public void raidRoomsFromTheUsersRealDeaths()
	{
		// the user's five Chambers of Xeric deaths (11-05 and 11-07): no attacker was seen on any of them
		assertEquals("Tekton", RaidRooms.cox(3318, 5299, 1, 13138));
		assertEquals("Great Olm", RaidRooms.cox(3228, 5743, 0, 12889));
		assertEquals("Great Olm", RaidRooms.cox(3230, 5745, 0, 12889));
		assertNull(RaidRooms.cox(3293, 9864, 0, 13210));             // Varrock Sewers (Scurrius): not the raid
		assertEquals("Great Olm", RaidRooms.boss("Great Olm Left claw"));
		assertEquals("Tekton", RaidRooms.boss("Tekton (enraged)"));
		assertEquals("Verzik Vitur", RaidRooms.boss("Verzik Vitur"));

		Death olm = new Death();
		olm.area = "Chambers of Xeric";
		olm.areaType = "RAIDS";
		olm.x = 3229;
		olm.y = 5742;
		olm.region = 12889;
		olm.cause = "hit";
		assertEquals("Great Olm", olm.killedBy());                 // was "Unknown"
		assertEquals("Great Olm", olm.who());
		assertTrue(olm.killerNote().contains("raid room"));

		Death none = new Death();
		none.cause = "hit";
		assertEquals(Death.NO_ATTACKER, none.killedBy());
		assertNull(none.who());

		Death seen = new Death();
		seen.area = "Chambers of Xeric";
		seen.region = 12889;
		seen.killer = "Great Olm";
		seen.killerLevel = 1043;
		assertEquals("Great Olm (level 1043)", seen.killedBy());
		assertNull(seen.killerNote());
	}

	@Test
	public void deathScreenshots()
	{
		// told from the game event that made RuneLite take the picture (ShotNamer), never from its file
		assertEquals(1794108559560L, DeathLogPlugin.ownDeath(new ShotNamer.Name(ShotNamer.DEATHS, ShotNamer.OWN_DEATH, 1794108559560L)));
		assertEquals(5L, DeathLogPlugin.ownDeath(new ShotNamer.Name(ShotNamer.DEATHS, ShotNamer.DOOM_DEATH, 5L)));
		assertEquals(-1, DeathLogPlugin.ownDeath(new ShotNamer.Name(ShotNamer.DEATHS, "Death Zezima", 5L)));   // a friend's
		assertEquals(-1, DeathLogPlugin.ownDeath(new ShotNamer.Name(ShotNamer.BOSS_KILLS, "Vorkath(852)", 5L)));
		assertEquals(-1, DeathLogPlugin.ownDeath(new ShotNamer.Name(null, "", 5L)));                         // a manual one
		// the live path end to end: your death queued, then a friend's, then the two pictures in that order
		ShotNamer n = new ShotNamer(new ShotNamerTest.Fake().with("playerDeath", true).with("friendDeath", true));
		n.death(true, "bycoo222", false, false, false, 1794108559560L);
		n.death(false, "Zezima", true, false, true, 1794108559600L);
		assertEquals(1794108559560L, DeathLogPlugin.ownDeath(n.take(1794108560000L)));
		assertEquals(-1, DeathLogPlugin.ownDeath(n.take(1794108560100L)));
		assertEquals(1794108559560L, Pictures.timeOf(Pictures.fileName(1794108559560L)));
		assertEquals(-1, Pictures.timeOf("gallery.json"));
	}

	@Test
	public void importFindsYourDeathScreenshotsWhicheverFolderYouPick()
	{
		ZoneId z = ZoneId.of("America/New_York");
		String f = "Death 2026-11-07_22-29-19.png";
		assertTrue(DeathImport.classify(List.of(".runelite", "screenshots", "bycoo222", "Deaths", f), "bycoo222", z) > 0);
		assertTrue(DeathImport.classify(List.of("screenshots", "bycoo222", "Deaths", f), "bycoo222", z) > 0);
		assertTrue(DeathImport.classify(List.of("bycoo222", "Deaths", f), null, z) > 0);       // your own folder
		assertTrue(DeathImport.classify(List.of("Deaths", f), null, z) > 0);                   // what the user picked 11-08
		assertEquals(DeathImport.SOMEONE_ELSE, DeathImport.classify(List.of("screenshots", "Zezima", "Deaths", f), "bycoo222", z));
		assertEquals(DeathImport.NOT_ONE, DeathImport.classify(
			List.of("screenshots", "bycoo222", "Deaths", "Death Zezima 2026-11-07_22-29-19.png"), "bycoo222", z));   // a friend's
		assertEquals(DeathImport.NOT_ONE, DeathImport.classify(List.of("screenshots", "bycoo222", "Boss Kills", f), "bycoo222", z));
		assertEquals(DeathImport.NOT_ONE, DeathImport.classify(List.of("Deaths"), "bycoo222", z));
		assertEquals(DeathImport.NOT_ONE, DeathImport.classify(List.of(".runelite", "plugin-data", "screenshot-gallery", "shots",
			"bycoo222", "Deaths", "Death 2026-11-07_22-29-19.jpg"), "bycoo222", z));            // the gallery's copies: not RuneLite's
	}

	private static Death death(long at, String killer, String area, String boss, int wave)
	{
		Death d = new Death();
		d.at = at;
		d.killer = killer;
		d.area = area;
		d.boss = boss;
		d.wave = wave;
		return d;
	}
